// The parts of the Files tab's editor that are a function of their arguments:
// what `<s TAB` and friends expand to, and what a capture template looks like
// written into the buffer as fields to step through. The editor itself
// (components/OrgTextEditor.tsx) only places the text and tracks the fields.
//
// An expansion is text plus fields, offsets relative to where it is inserted.
// A field is a span of that text the cursor visits in turn; two fields with the
// same key are one value written twice, and the first is the one typed into.

import { CaptureTemplate, placeholderParts, autoValue, needsHeadline, isContentKey } from './capture';

export type FieldKind = 'text' | 'tags';

export type ExpField = {
    from: number;
    to: number;
    key: string;
    // Shown faintly in the field while it is empty, so a field says what it is
    // for without the words having to be typed over.
    prompt: string;
    kind: FieldKind;
};

export type Expansion = { text: string; fields: ExpField[] };

// `${key:prompt}` marks a field in the snippet strings below; `${key:prompt=v}`
// starts it holding v. Written this way so a snippet reads as what it inserts.
const MARK = /\$\{([^:}]+):([^}=]*)(?:=([^}]*))?\}/g;

export function expandMarked(src: string, indent: string = ''): Expansion {
    const lines = src.split('\n').map((l, i) => (i === 0 || l === '' ? l : indent + l));
    const joined = lines.join('\n');
    let text = '';
    const fields: ExpField[] = [];
    let at = 0;
    let m: RegExpExecArray | null;
    MARK.lastIndex = 0;
    while ((m = MARK.exec(joined)) !== null) {
        text += joined.slice(at, m.index);
        const initial = m[3] || '';
        fields.push({ from: text.length, to: text.length + initial.length, key: m[1], prompt: m[2], kind: m[1] === '__tags' ? 'tags' : 'text' });
        text += initial;
        at = m.index + m[0].length;
    }
    text += joined.slice(at);
    return { text, fields };
}

// org-tempo's table, with `<c` taken for capture (org-tempo has it as
// center, which is `<C` here).
export const TEMPO: Record<string, { label: string; src: string }> = {
    s: { label: 'source block', src: '#+BEGIN_SRC ${lang:language}\n${body:code}\n#+END_SRC' },
    e: { label: 'example block', src: '#+BEGIN_EXAMPLE\n${body:example}\n#+END_EXAMPLE' },
    q: { label: 'quote block', src: '#+BEGIN_QUOTE\n${body:quote}\n#+END_QUOTE' },
    v: { label: 'verse block', src: '#+BEGIN_VERSE\n${body:verse}\n#+END_VERSE' },
    C: { label: 'center block', src: '#+BEGIN_CENTER\n${body:text}\n#+END_CENTER' },
    x: { label: 'export block', src: '#+BEGIN_EXPORT ${fmt:format}\n${body:text}\n#+END_EXPORT' },
    h: { label: 'html export', src: '#+BEGIN_EXPORT html\n${body:html}\n#+END_EXPORT' },
    l: { label: 'latex export', src: '#+BEGIN_EXPORT latex\n${body:latex}\n#+END_EXPORT' },
    a: { label: 'ascii export', src: '#+BEGIN_EXPORT ascii\n${body:text}\n#+END_EXPORT' },
    I: { label: 'include', src: '#+INCLUDE: "${file:file}"' },
    tb: { label: 'table', src: '| ${h1:column} | ${h2:column} |\n|---+---|\n| ${c1:} | ${c2:} |' },
    cb: { label: 'checkbox item', src: '- [ ] ${item:item}' },
    n: { label: 'name', src: '#+NAME: ${name:name}' },
};

// The expansions that depend on where they are, done by orgcmds.ts rather
// than by inserting text: the `<p` goes and a property lands in the heading's
// drawer, `<sch` lands on the heading's planning line, and so on.
export const SMART: Record<string, string> = {
    p: 'property (in the heading\'s drawer)',
    sch: 'SCHEDULED on the heading',
    dl: 'DEADLINE on the heading',
    t: 'active timestamp, today',
    i: 'inactive timestamp, now',
};

// The `<x` (or `<sch`) just before the cursor, when it is all there is on the line before
// it apart from indentation: org-tempo only fires at the start of a line, which
// is what keeps `a<b` in prose from turning into a block.
export function tempoBefore(lineBefore: string): { key: string; indent: string } | null {
    const m = /^(\s*)<([A-Za-z]+)$/.exec(lineBefore);
    if (m === null) return null;
    const own = (o: object, k: string) => Object.prototype.hasOwnProperty.call(o, k);
    if (m[2] !== 'c' && !own(TEMPO, m[2]) && !own(SMART, m[2])) return null;
    return { key: m[2], indent: m[1] };
}

// How deep a captured entry goes: one under the heading the cursor is in, or a
// top-level heading when it is above the first one.
export function captureLevel(linesAbove: string[]): number {
    for (let i = linesAbove.length - 1; i >= 0; i--) {
        const h = /^(\*+)\s/.exec(linesAbove[i]);
        if (h !== null) return h[1].length + 1;
    }
    return 1;
}

const PLACEHOLDER = /\{\{\s*([^}|]+?)\s*(?:\|([^}]*?))?\}\}/g;

// A {{NAME}} template turned into marked text: a name that answers itself
// (the date, a uuid the server filled in) is written as its answer, and
// everything else becomes a field. The rules are capture.ts's, so a template
// asks for the same things inline as it does in the capture dialog.
function markTemplate(template: string, now: Date): string {
    // A literal $ would read as the start of a mark; it is hidden as \0 and
    // put back by the caller. A } inside a default would end the mark early.
    const esc = (s: string) => s.replace(/\$/g, '\u0000');
    return template.replace(PLACEHOLDER, (_all, rawKey: string, rest: string) => {
        const key = rawKey.trim();
        const { prompt, dflt, hasDefault } = placeholderParts(rest || '');
        const auto = hasDefault ? dflt : autoValue(key, now);
        // Something the clock or the server answered is not a question.
        if (auto !== null && !(hasDefault && prompt !== '')) return esc(auto);
        const label = prompt || (isContentKey(key) ? 'content' : key.toLowerCase());
        return '${' + key + ':' + label.replace(/[}:=]/g, ' ') + (hasDefault && dflt !== '' ? '=' + esc(dflt).replace(/}/g, '') : '') + '}';
    });
}

// A capture template written into the buffer as an expansion. The shape
// follows the template's type the way the capture dialog's preview does: an
// entry is a heading (with a tags field after the title), an item a list item,
// a checkitem a checkbox, a table line a row; the template string is the body.
export function captureExpansion(t: CaptureTemplate, level: number, indent: string = '', now: Date = new Date()): Expansion {
    const type = (t.Type || 'entry').trim().toLowerCase();
    const body = (t.Template || '').trim() === '' ? '${CONTENT:content}' : markTemplate(t.Template, now);
    let src: string;
    if (needsHeadline(type)) {
        src = `${'*'.repeat(Math.max(1, level))} \${__headline:headline} \${__tags:tags}\n${body}`;
        // A heading starts its line, whatever the cursor was indented by.
        indent = '';
    } else if (type === 'item') {
        src = `- ${body}`;
    } else if (type === 'checkitem') {
        src = `- [ ] ${body}`;
    } else if (type === 'table-line') {
        src = `| ${body} |`;
    } else {
        src = body;
    }
    const exp = expandMarked(src, indent);
    // markTemplate hid a literal $ from expandMarked; put it back.
    return { text: exp.text.replace(/\u0000/g, '$'), fields: exp.fields };
}

// What a tags field is written as when the capture is finished: "work home"
// or "work:home" becomes "  :work:home:", nothing becomes nothing.
export function formatTags(raw: string): string {
    const tags = raw.split(/[\s:,]+/).map(s => s.trim()).filter(Boolean);
    return tags.length === 0 ? '' : `  :${tags.join(':')}:`;
}

// Whether a line left behind by a finished capture should go: a line that was
// a field and nothing else, left empty, or a property with no value - the same
// rule fillTemplate follows, so an inline capture writes what the dialog would.
export function isLeftoverLine(line: string): boolean {
    return line.trim() === '' || /^\s*:[^:\s]+:\s*$/.test(line);
}
