// What a card can find in the text written under its heading.
//
// Three things, all read from the body as it is in the file rather than from
// the rendered html: a checklist, a recording, and a picture. The html is
// right for reading and no use for any of them - a rendered `- [ ]` is a
// disabled input with no way back to the line it came from, and a rendered
// link has already been turned into whatever the exporter thought it should
// be.
//
// Pure on purpose. Which lines are checkboxes and how many are ticked is the
// sort of thing that is wrong quietly - a count that says 2/5 when it is 3/5
// is not a crash, it is a card that lies - so it is worth pinning.

export interface CheckItem {
    // Position among the checkboxes of this body, which is what the server
    // counts to find the line again.
    index: number;
    done: boolean;
    text: string;
    // How far in it sits, in bullet levels rather than spaces, so a nested
    // list reads as one.
    depth: number;
}

export interface Checklist {
    items: CheckItem[];
    done: number;
    total: number;
}

// An org checklist item: optional indent, a bullet, a box, and the rest. The
// same shape the server matches - they have to agree, because the client
// counts the items and the server counts them again to find the line.
//
// `*` is a bullet only when it is indented. At column zero it is a heading,
// and `* [ ] something` is a heading whose text happens to start with a box -
// counting it would put an item on the card that belongs to another card.
const ITEM = /^(\s*)([-+*]|\d+[.)])\s+\[([ xX-])\]\s?(.*)$/;

function itemOf(line: string): RegExpMatchArray | null {
    const m = line.match(ITEM);
    if (!m) return null;
    if (m[2] === '*' && m[1] === '') return null;
    return m;
}

// Lines that are not body text: the planning line, a drawer and its contents,
// and the property drawer. A card should not offer to tick something out of a
// LOGBOOK.
const DRAWER_OPEN = /^\s*:[A-Za-z0-9_@#%-]+:\s*$/;
const DRAWER_END = /^\s*:END:\s*$/i;
const PLANNING = /^\s*(SCHEDULED|DEADLINE|CLOSED):/;

// The body's own lines, with the drawers and planning taken out.
export function bodyLines(text: string): string[] {
    const out: string[] = [];
    if ((text || '') === '') return out;
    let inDrawer = false;
    for (const line of (text || '').split('\n')) {
        if (inDrawer) {
            if (DRAWER_END.test(line)) inDrawer = false;
            continue;
        }
        if (DRAWER_OPEN.test(line) && !DRAWER_END.test(line)) { inDrawer = true; continue; }
        if (PLANNING.test(line)) continue;
        out.push(line);
    }
    return out;
}

export function checklistOf(text: string): Checklist {
    const items: CheckItem[] = [];
    for (const line of bodyLines(text)) {
        const m = itemOf(line);
        if (!m) continue;
        items.push({
            index: items.length,
            // `-` is org's "some of the children are done" state. It is not
            // done, and treating it as done would make the count say a thing
            // is finished when org says it is half finished.
            done: m[3] === 'x' || m[3] === 'X',
            text: m[4].trim(),
            depth: Math.floor(m[1].replace(/\t/g, '  ').length / 2),
        });
    }
    return {
        items,
        done: items.filter(i => i.done).length,
        total: items.length,
    };
}

// ---------------------------------------------------------------------------
// Links
// ---------------------------------------------------------------------------

const AUDIO_EXT = ['.mp3', '.wav', '.ogg', '.oga', '.opus', '.webm', '.weba', '.m4a', '.aac', '.flac'];
const IMAGE_EXT = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.avif', '.bmp'];

function extensionOf(target: string): string {
    const clean = target.split(/[?#]/)[0];
    const dot = clean.lastIndexOf('.');
    return dot < 0 ? '' : clean.slice(dot).toLowerCase();
}

export function isAudio(target: string): boolean {
    return AUDIO_EXT.indexOf(extensionOf(target)) >= 0;
}

export function isImage(target: string): boolean {
    return IMAGE_EXT.indexOf(extensionOf(target)) >= 0;
}

// The target a link points at, whatever shape it was written in: an org link
// with or without a description, a bare `file:` link, or a plain path. The
// same reading the html exporter does, because a card and the exported page
// should not disagree about what a heading points at.
export function linkTarget(v: string): string {
    let s = (v || '').trim();
    if (s === '') return '';
    if (s.slice(0, 2) === '[[') {
        const end = s.indexOf(']]');
        if (end < 0) return '';
        s = s.slice(2, end);
        const desc = s.indexOf('][');
        if (desc >= 0) s = s.slice(0, desc);
    }
    s = s.trim();
    if (s.slice(0, 7) === 'file://') s = s.slice(7);
    else if (s.slice(0, 5) === 'file:') s = s.slice(5);
    return s.trim();
}

// Every link in the body, in the order they are written.
export function linksIn(text: string): string[] {
    const out: string[] = [];
    const re = /\[\[([^\]]+)\](?:\[[^\]]*\])?\]/g;
    const body = bodyLines(text).join('\n');
    let m = re.exec(body);
    while (m !== null) {
        const t = linkTarget(`[[${m[1]}]]`);
        if (t !== '') out.push(t);
        m = re.exec(body);
    }
    return out;
}

// The first recording a heading points at: a property first, because that is
// where a voice note writes it, then anything in the text.
export function audioIn(text: string, props: Record<string, string> | null | undefined): string {
    for (const key of Object.keys(props || {})) {
        const t = linkTarget((props || {})[key]);
        if (t !== '' && isAudio(t)) return t;
    }
    for (const t of linksIn(text)) if (isAudio(t)) return t;
    return '';
}

// The first picture a heading points at, read the same way round.
export function imageIn(text: string, props: Record<string, string> | null | undefined): string {
    for (const key of Object.keys(props || {})) {
        const t = linkTarget((props || {})[key]);
        if (t !== '' && isImage(t)) return t;
    }
    for (const t of linksIn(text)) if (isImage(t)) return t;
    return '';
}

// Every picture a heading points at, not only the first: a node can carry a
// handful, and the inspect view has room to show them where a card does not.
export function imagesIn(text: string, props: Record<string, string> | null | undefined): string[] {
    const out: string[] = [];
    const take = (t: string) => { if (t !== '' && isImage(t) && out.indexOf(t) < 0) out.push(t); };
    for (const key of Object.keys(props || {})) take(linkTarget((props || {})[key]));
    for (const t of linksIn(text)) take(t);
    return out;
}

// ---------------------------------------------------------------------------
// Tables
// ---------------------------------------------------------------------------
//
// Enough of an org table to draw one. Not enough to edit it - that is the
// Tables tab's job, and it reads the table from the server with its formulas,
// column names and cell references. This is for showing one where it was
// written.

export interface OrgTableRow {
    // A rule is the `|----+----|` line: a divider rather than a row of values.
    rule: boolean;
    cells: string[];
}

export interface OrgTable {
    // The `#+NAME:` above it, when it has one.
    name: string;
    rows: OrgTableRow[];
    // Widest row, so every row can be padded to the same shape.
    cols: number;
    // The `#+TBLFM:` lines under it, as written. Not evaluated here - nothing
    // in this file computes a cell - but worth keeping, because a table with
    // formulas is a table whose numbers came from somewhere and a reader
    // looking at one wants to see where.
    formulas: string[];
}

const TABLE_LINE = /^\s*\|/;
const NAME_LINE = /^\s*#\+NAME:\s*(.+)$/i;
const FORMULA_LINE = /^\s*#\+TBLFM:\s*(.*)$/i;

function splitRow(line: string): OrgTableRow {
    const body = line.trim().replace(/^\|/, '').replace(/\|\s*$/, '');
    // A rule is dashes and pluses and nothing else.
    if (/^[-+|\s]*$/.test(body) && body.indexOf('-') >= 0) {
        return { rule: true, cells: [] };
    }
    return { rule: false, cells: body.split('|').map(c => c.trim()) };
}

// The tables in a body, in the order they are written.
export function tablesIn(text: string): OrgTable[] {
    const lines = bodyLines(text);
    const out: OrgTable[] = [];
    let cur: OrgTable | null = null;
    let name = '';

    for (const line of lines) {
        const named = line.match(NAME_LINE);
        if (named) { name = named[1].trim(); continue; }
        // A formula line belongs to the table above it, and does not end it:
        // org allows several, one after another.
        const formula = line.match(FORMULA_LINE);
        if (formula) {
            if (cur && formula[1].trim() !== '') cur.formulas.push(formula[1].trim());
            continue;
        }
        if (TABLE_LINE.test(line)) {
            if (!cur) { cur = { name, rows: [], cols: 0, formulas: [] }; name = ''; }
            const row = splitRow(line);
            cur.rows.push(row);
            if (row.cells.length > cur.cols) cur.cols = row.cells.length;
            continue;
        }
        if (cur) {
            // A blank line inside a table is the end of it, which is what org
            // says too.
            out.push(cur);
            cur = null;
        }
        if (line.trim() !== '') name = '';
    }
    if (cur) out.push(cur);
    return out.filter(t => t.rows.some(r => !r.rule));
}
