// ---------------------------------------------------------------------------
// A card
// ---------------------------------------------------------------------------

type CardProps = {
    card: Card;
    board: KanbanBoard;
    flipped: boolean;
    dim: boolean;
    dragging: boolean;
    onFlip: () => void;
    onDragStart: (e: React.DragEvent) => void;
    onDragEnd: () => void;
    onDragOverCard: (e: React.DragEvent) => void;
    onAct: (what: CardAction, card: Card) => void;
    clocked: boolean;
    // The labels this board offers, and how to put one on a heading.
    labelChoices: string[];
    onToggleLabel: (card: Card, value: string) => void;
};

// The bar across the top of a card. Thin on purpose: it is a mark, not a
// heading - the card's own words are what the reader is here for.
function CardHeader({ card, board, dark }: { card: Card; board: KanbanBoard; dark: boolean }) {
    const value = headerValueOf(card, board);
    return (
        <Box
            title={value ? `${(board.headerKey || 'COLOUR').toUpperCase()}: ${value}` : undefined}
            sx={{
                height: 4,
                flexShrink: 0,
                background: headerColorOf(card, board, dark),
                // Squared off against the card's own rounding, so the bar looks
                // built into the card rather than laid on top of it.
                borderTopLeftRadius: 'inherit',
                borderTopRightRadius: 'inherit',
            }}
        />
    );
}

// The coloured bars across the top of a card's face. Small, wide and close
// together, so that five of them read as a pattern rather than as five things
// to look at - which is the whole point of categorising at a glance.
function CardLabels({ card, board }: { card: Card; board: KanbanBoard }) {
    const labels = labelsOf(card, board);
    if (labels.length === 0) return null;
    return (
        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mb: 0.25 }}>
            {labels.map(v => (
                <Tooltip key={v} size="sm" title={v}>
                    <Box sx={{
                        height: 6, minWidth: 30, flex: '0 1 44px', borderRadius: 3,
                        background: labelColorOf(v, board),
                    }} />
                </Tooltip>
            ))}
        </Box>
    );
}

function CardFront({ card, board, sw, dark }: {
    card: Card; board: KanbanBoard; sw: { hex: string } | null; dark: boolean;
}) {
    const body = useHeadingBody(card.Hash);
    const tags = card.Tags || [];
    const badges = (board.badges || [])
        .map(name => ({ name, value: card.Props ? card.Props[name] : undefined }))
        .filter(b => b.value !== undefined && b.value !== '');
    const deadline = isSetDate(card.Deadline) ? card.Deadline!.Start! : '';
    const scheduled = isSetDate(card.Date) ? card.Date!.Start! : '';
    // The keyword is worth a chip except on a board that is already split by
    // it, where every card in a column would wear the same one.
    const showStatus = card.Status !== '' && board.groupBy !== 'status';

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', minWidth: 0 }}>
            <CardHeader card={card} board={board} dark={dark} />
            <Box sx={{ p: 1.25, pl: 1.5, display: 'flex', flexDirection: 'column', gap: 0.75, flex: 1, minWidth: 0 }}>
            <CardLabels card={card} board={board} />
            {/* A picture the heading points at, above its own words - which is
                where a picture goes on a card everywhere else. */}
            <CardImage src={body.image} alt={card.Headline} />
            <Box sx={{ display: 'flex', gap: 0.75, alignItems: 'flex-start', minWidth: 0 }}>
                {card.Priority && (
                    <Box
                        sx={{
                            flexShrink: 0, mt: '2px', px: 0.5, borderRadius: 3, fontSize: 10, fontWeight: 'lg',
                            lineHeight: '16px', color: '#fff',
                            background: PRIORITY_COLOR[card.Priority.toUpperCase()] || '#6b7280',
                        }}
                    >
                        {card.Priority.toUpperCase()}
                    </Box>
                )}
                <Typography
                    level="body-sm"
                    sx={{
                        fontWeight: 'md', lineHeight: 1.35, minWidth: 0,
                        display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden',
                    }}
                >
                    {card.Headline || '(no headline)'}
                </Typography>
            </Box>

            {(showStatus || tags.length > 0 || badges.length > 0 || body.list.total > 0) && (
                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', alignItems: 'center' }}>
                    <ChecklistBadge list={body.list} />
                    {showStatus && (
                        <Chip size="sm" variant="soft" color="neutral" sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}>
                            {card.Status}
                        </Chip>
                    )}
                    {badges.map(b => (
                        <Chip
                            key={b.name}
                            size="sm"
                            variant="outlined"
                            sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}
                            title={`${b.name}: ${b.value}`}
                        >
                            {b.value}
                        </Chip>
                    ))}
                    {tags.map(t => (
                        <Box
                            key={t}
                            sx={{
                                fontSize: 10, px: 0.6, borderRadius: 3, lineHeight: '16px',
                                background: tint(autoSwatch(t).hex, 0.18),
                                color: 'text.secondary',
                            }}
                        >
                            {t}
                        </Box>
                    ))}
                </Box>
            )}

            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', mt: 'auto', minWidth: 0 }}>
                {deadline && (
                    <Tooltip size="sm" title={`Deadline ${deadline.substring(0, 10)}`}>
                        <Box sx={{
                            display: 'flex', alignItems: 'center', gap: 0.25, fontSize: 10,
                            color: isOverdue(deadline) ? 'danger.500' : 'text.tertiary',
                            fontWeight: isOverdue(deadline) ? 'lg' : 'md',
                        }}>
                            <FlagIcon sx={{ fontSize: 12 }} />{dateLabel(deadline)}
                        </Box>
                    </Tooltip>
                )}
                {scheduled && (
                    <Tooltip size="sm" title={`Scheduled ${scheduled.substring(0, 10)}`}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25, fontSize: 10, color: 'text.tertiary' }}>
                            <ScheduleIcon sx={{ fontSize: 12 }} />{dateLabel(scheduled)}
                        </Box>
                    </Tooltip>
                )}
                <Typography level="body-xs" sx={{ ml: 'auto', color: 'text.tertiary', fontSize: 10 }} noWrap title={card.Filename}>
                    {baseName(card.Filename)}
                </Typography>
            </Box>

            </Box>

            {/* The colour-by stripe runs down the side, under the header bar
                rather than through it - the two say different things and should
                not be mistaken for one shape. */}
            {sw && <Box sx={{ position: 'absolute', left: 0, top: 4, bottom: 0, width: 4, background: sw.hex, borderRadius: '0 0 0 6px' }} />}
        </Box>
    );
}

// The back of a card: the same detail with the card's own bar and headline
// over it, because a face that has turned over has to say what it is.
function CardBack({ card, board, clocked, dark, onAct }: {
    card: Card; board: KanbanBoard; clocked: boolean; dark: boolean;
    onAct: (what: CardAction, card: Card) => void;
}) {
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', minWidth: 0 }}>
            {/* The same bar as the front: a card turned over is still the
                same card, and the mark is how it is picked out of a column. */}
            <CardHeader card={card} board={board} dark={dark} />
            <Box sx={{ p: 1.25, display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, minWidth: 0 }}>
                <Typography level="body-xs" sx={{ fontWeight: 'lg', mb: 0.5 }} noWrap title={card.Headline}>
                    {card.Headline}
                </Typography>
                <CardDetail card={card} board={board} clocked={clocked} onAct={onAct} />
            </Box>
        </Box>
    );
}

// Adding a label to the heading. The menu is the board's own set, ticked where
// the heading already carries one, so this is picking from a few rather than
// typing a tag and hoping it matches what the board colours.
function LabelMenu({ card, board, choices, onToggle }: {
    card: Card;
    board: KanbanBoard;
    choices: string[];
    onToggle: (card: Card, value: string) => void;
}) {
    const has = labelsOf(card, board);
    const what = board.labelSource === 'tags' ? 'tag' : (board.labelKey || 'property').toUpperCase();
    return (
        <Dropdown>
            <Tooltip size="sm" title={`Labels — writes a ${what} on this heading`}>
                <MenuButton
                    slots={{ root: IconButton }}
                    slotProps={{ root: { size: 'sm', variant: 'plain', color: 'neutral' } }}
                    sx={{ '--IconButton-size': '22px', minWidth: 22 }}
                >
                    <LocalOfferIcon sx={{ fontSize: 13 }} />
                </MenuButton>
            </Tooltip>
            <Menu size="sm" placement="bottom-end" sx={{ minWidth: 190 }}>
                {choices.length === 0 ? (
                    <MenuItem disabled>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            No labels set up on this board yet.
                        </Typography>
                    </MenuItem>
                ) : choices.map(v => {
                    const on = has.indexOf(v) >= 0;
                    return (
                        <MenuItem key={v} onClick={() => onToggle(card, v)} selected={on}>
                            <Box sx={{
                                width: 22, height: 8, borderRadius: 4, flexShrink: 0,
                                background: labelColorOf(v, board),
                            }} />
                            <Typography level="body-sm" sx={{ flex: 1, minWidth: 0 }} noWrap>{v}</Typography>
                            {on && <CheckIcon sx={{ fontSize: 14, color: 'text.tertiary' }} />}
                        </MenuItem>
                    );
                })}
            </Menu>
        </Dropdown>
    );
}

// A card is two faces turned by a click and a thing you can pick up and drop
// somewhere else.
//
// The height is the front's own - a third copy of the front is rendered in the
// flow, hidden, purely to give the box a height, because a face that turns has
// to be positioned absolutely and an absolute box has no height of its own. The
// back is given room to breathe when it is showing and gives it back when it is
// not, which is what the min-height transition is.
function KanbanCardView(props: CardProps) {
    const {
        card, board, flipped, dim, dragging, onFlip, onDragStart, onDragEnd,
        onDragOverCard, onAct, clocked, labelChoices, onToggleLabel,
    } = props;
    const sw = cardSwatch(card, board);
    // Only used to pick the shade of "this card says nothing about its colour",
    // which has to differ from the card it sits on.
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    // A drag that ends over the same card still fires a click in some browsers,
    // so the flip asks whether a drag has just happened rather than trusting it.
    const dragged = React.useRef(false);
    // The back is built the first time the card is turned over and then kept,
    // so turning it back and forth does not fetch the text again. Before that
    // the face is there but empty - it is facing away from the reader, and what
    // it would have cost is a request per card on the board.
    const [revealed, setRevealed] = React.useState(flipped);
    if (flipped && !revealed) setRevealed(true);

    const faceSx = {
        position: 'absolute' as const,
        inset: 0,
        borderRadius: 'sm',
        overflow: 'hidden',
        backfaceVisibility: 'hidden' as const,
        WebkitBackfaceVisibility: 'hidden' as const,
        border: '1px solid',
        borderColor: sw ? tint(sw.hex, 0.45) : 'divider',
        background: sw
            ? `linear-gradient(180deg, ${tint(sw.hex, 0.14)}, ${tint(sw.hex, 0.05)}), var(--joy-palette-background-surface)`
            : 'var(--joy-palette-background-surface)',
        boxShadow: 'sm',
    };

    return (
        <Box
            draggable
            onDragStart={e => { dragged.current = true; onDragStart(e); }}
            onDragEnd={() => { onDragEnd(); window.setTimeout(() => { dragged.current = false; }, 0); }}
            onDragOver={onDragOverCard}
            onClick={() => { if (!dragged.current) onFlip(); }}
            sx={{
                position: 'relative',
                perspective: '1400px',
                cursor: 'grab',
                mb: 1,
                opacity: dragging ? 0.35 : dim ? 0.35 : 1,
                filter: dim ? 'saturate(0.3)' : 'none',
                transition: 'opacity 0.2s, filter 0.2s, min-height 0.3s ease',
                minHeight: flipped ? 210 : 0,
                '&:active': { cursor: 'grabbing' },
                '&:hover .kb-flip': { opacity: 1 },
                '&:hover .kb-labels': { opacity: 1 },
            }}
        >
            {/* The sizer: the front again, in the flow and invisible, so the
                card is as tall as its own headline rather than a guess. */}
            <Box sx={{ visibility: 'hidden', pointerEvents: 'none' }} aria-hidden>
                <CardFront card={card} board={board} sw={sw} dark={dark} />
            </Box>

            <Box
                sx={{
                    position: 'absolute', inset: 0,
                    transformStyle: 'preserve-3d',
                    transition: 'transform 0.55s cubic-bezier(0.2, 0.7, 0.25, 1)',
                    transform: flipped ? 'rotateY(180deg)' : 'rotateY(0deg)',
                }}
            >
                <Sheet sx={faceSx}>
                    <CardFront card={card} board={board} sw={sw} dark={dark} />
                </Sheet>
                <Sheet sx={{ ...faceSx, transform: 'rotateY(180deg)' }}>
                    {revealed && (
                        <CardBack
                            card={card}
                            board={board}
                            clocked={clocked}
                            dark={dark}
                            onAct={onAct}
                        />
                    )}
                </Sheet>
            </Box>

            <Box
                className="kb-flip"
                sx={{
                    // Clear of the header bar, which now owns the top 4px.
                    position: 'absolute', top: 6, right: 3, opacity: 0, transition: 'opacity 0.15s',
                    pointerEvents: 'none', color: 'text.tertiary',
                }}
            >
                <FlipIcon sx={{ fontSize: 13 }} />
            </Box>

            {/* The label menu, at the foot of the card and only while the
                pointer is on it. A card is mostly read, not edited, and a
                control sitting on every card all the time is a control in the
                way of the words. */}
            {board.labelSource !== 'none' && !flipped && (
                <Box
                    className="kb-labels"
                    onClick={e => e.stopPropagation()}
                    sx={{
                        position: 'absolute', bottom: 3, right: 3,
                        opacity: 0, transition: 'opacity 0.15s',
                    }}
                >
                    <LabelMenu card={card} board={board} choices={labelChoices} onToggle={onToggleLabel} />
                </Box>
            )}
        </Box>
    );
}

// ---------------------------------------------------------------------------
// A column
// ---------------------------------------------------------------------------

function Column({
    col, cards, board, flipped, terms, dropIndex, isDropTarget, draggingHash, clockedHash,
    onFlip, onCollapse, onDragStart, onDragEnd, onDragOverAt, onDrop, onAct, dropRefused,
    labelChoices, onToggleLabel,
}: {
    col: KanbanColumn;
    cards: Card[];
    board: KanbanBoard;
    flipped: Set<string>;
    terms: string[];
    dropIndex: number | null;
    isDropTarget: boolean;
    draggingHash: string | null;
    clockedHash: string;
    onFlip: (hash: string) => void;
    onCollapse: (value: string, collapsed: boolean) => void;
    onDragStart: (card: Card) => void;
    onDragEnd: () => void;
    onDragOverAt: (value: string, index: number) => void;
    onDrop: (value: string) => void;
    onAct: (what: CardAction, card: Card) => void;
    dropRefused: boolean;
    labelChoices: string[];
    onToggleLabel: (card: Card, value: string) => void;
}) {
    const isMobile = useIsMobile();
    const sw = col.color ? swatch(col.color) : autoSwatch(col.value || 'unset');
    const over = col.limit > 0 && cards.length > col.limit;
    const title = columnTitle(col) || 'Untitled';
    const values = columnValues(col);

    if (col.collapsed) {
        return (
            <Sheet
                variant="outlined"
                sx={{
                    width: 44, flexShrink: 0, borderRadius: 'sm', display: 'flex', flexDirection: 'column',
                    alignItems: 'center', py: 1, gap: 1, cursor: 'pointer',
                    borderTop: '3px solid', borderTopColor: sw.hex,
                    background: tint(sw.hex, 0.06),
                }}
                onClick={() => onCollapse(col.value, false)}
            >
                <Tooltip size="sm" title={`Open ${title}`}>
                    <ChevronRightIcon fontSize="small" />
                </Tooltip>
                <Chip size="sm" variant="soft" sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}>{cards.length}</Chip>
                <Typography
                    level="body-xs"
                    sx={{
                        writingMode: 'vertical-rl', textOrientation: 'mixed', fontWeight: 'lg',
                        color: 'text.secondary', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis',
                    }}
                >
                    {title}
                </Typography>
            </Sheet>
        );
    }

    return (
        <Sheet
            variant="outlined"
            onDragOver={e => {
                e.preventDefault();
                // Over the column but not over any card: the end of the list.
                onDragOverAt(col.value, cards.length);
            }}
            onDrop={e => { e.preventDefault(); onDrop(col.value); }}
            sx={{
                // A phone gets a column just under the width of the screen: a
                // sliver of the next one showing is what tells you the board
                // scrolls sideways at all, and 300px on a 390px screen is two
                // half columns and no cards you can read. Snapping makes the
                // sideways scroll land on a column rather than between two.
                width: isMobile ? 'min(300px, 86vw)' : 300,
                scrollSnapAlign: isMobile ? 'start' : undefined,
                flexShrink: 0, borderRadius: 'sm', display: 'flex', flexDirection: 'column',
                minHeight: 0, maxHeight: '100%',
                borderTop: '3px solid', borderTopColor: sw.hex,
                background: isDropTarget
                    ? (dropRefused ? 'var(--joy-palette-danger-softBg)' : tint(sw.hex, 0.09))
                    : 'var(--joy-palette-background-level1)',
                transition: 'background 0.15s',
            }}
        >
            {/* While a card is in the air, a column that answers to more than one
                spelling offers one square per spelling: the column is one
                place, but dropping still has to write one particular value.
                Only during a drag - the rest of the time they would be a row of
                buttons nobody asked for. */}
            {draggingHash !== null && values.length > 1 && (
                <Box sx={{ px: 1, pt: 1, display: 'flex', gap: 0.5, flexWrap: 'wrap', flexShrink: 0 }}>
                    {values.map(v => (
                        <Box
                            key={v}
                            onDragOver={e => { e.preventDefault(); e.stopPropagation(); onDragOverAt(col.value, cards.length); }}
                            onDrop={e => { e.preventDefault(); e.stopPropagation(); onDrop(v); }}
                            sx={{
                                flex: '1 1 auto', minWidth: 0, px: 0.75, py: 0.5,
                                borderRadius: 'sm', border: '1px dashed', borderColor: sw.hex,
                                background: tint(sw.hex, 0.10),
                                textAlign: 'center', cursor: 'copy',
                                '&:hover': { background: tint(sw.hex, 0.28) },
                            }}
                        >
                            <Typography level="body-xs" noWrap sx={{ fontWeight: 'lg' }}>{v}</Typography>
                        </Box>
                    ))}
                </Box>
            )}

            <Box sx={{ px: 1.25, py: 1, display: 'flex', alignItems: 'center', gap: 0.75, flexShrink: 0 }}>
                <Box sx={{ width: 8, height: 8, borderRadius: '50%', background: sw.hex, flexShrink: 0 }} />
                <Typography level="title-sm" noWrap sx={{ minWidth: 0 }} title={col.value || title}>
                    {title}
                </Typography>
                <Tooltip size="sm" title={col.limit > 0 ? `${cards.length} of at most ${col.limit}` : `${cards.length} cards`}>
                    <Chip
                        size="sm"
                        variant={over ? 'solid' : 'soft'}
                        color={over ? 'danger' : 'neutral'}
                        sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}
                    >
                        {col.limit > 0 ? `${cards.length}/${col.limit}` : cards.length}
                    </Chip>
                </Tooltip>
                <IconButton
                    size="sm" variant="plain" color="neutral" sx={{ ml: 'auto' }}
                    onClick={() => onCollapse(col.value, true)}
                >
                    <ChevronLeftIcon sx={{ fontSize: 16 }} />
                </IconButton>
            </Box>

            <Box sx={{ px: 1, pb: 1, overflowY: 'auto', overflowX: 'hidden', flex: 1, minHeight: 60 }}>
                {cards.length === 0 && (
                    <Box sx={{
                        border: '1px dashed', borderColor: 'divider', borderRadius: 'sm',
                        p: 2, textAlign: 'center',
                    }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {draggingHash ? 'Drop here' : 'Nothing here'}
                        </Typography>
                    </Box>
                )}
                {cards.map((c, i) => (
                    <React.Fragment key={c.Hash}>
                        {isDropTarget && dropIndex === i && !dropRefused && (
                            <Box sx={{ height: 3, borderRadius: 2, background: sw.hex, mb: 1, mt: -0.25 }} />
                        )}
                        <KanbanCardView
                            card={c}
                            board={board}
                            flipped={flipped.has(c.Hash)}
                            dim={terms.length > 0 && !cardMatches(c, terms)}
                            dragging={draggingHash === c.Hash}
                            clocked={clockedHash === c.Hash}
                            onFlip={() => onFlip(c.Hash)}
                            onDragStart={() => onDragStart(c)}
                            onDragEnd={onDragEnd}
                            onDragOverCard={e => {
                                e.preventDefault();
                                e.stopPropagation();
                                const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
                                onDragOverAt(col.value, e.clientY < r.top + r.height / 2 ? i : i + 1);
                            }}
                            onAct={onAct}
                            labelChoices={labelChoices}
                            onToggleLabel={onToggleLabel}
                        />
                    </React.Fragment>
                ))}
                {isDropTarget && dropIndex === cards.length && cards.length > 0 && !dropRefused && (
                    <Box sx={{ height: 3, borderRadius: 2, background: sw.hex, mb: 1 }} />
                )}
            </Box>
        </Sheet>
    );
}

// ---------------------------------------------------------------------------
// The board
// ---------------------------------------------------------------------------

// Loaded lazily so that the dialog's weight is not on the path of opening a
// board, which is what every session starts with.
const KanbanSettings = React.lazy(() => import('./KanbanSettings'));
// The other layout. Lazy for the same reason: a board opened as columns should
// not pay for the table, and the other way round.
const KanbanList = React.lazy(() => import('./KanbanList'));

export default function Kanban() {
    const isMobile = useIsMobile();
    const chrome = useChromeToggle();
    const [lastBoard, setLastBoard] = useSetting('kanbanBoard');

    const [boards, setBoards] = React.useState<KanbanBoard[]>([]);
    const [loadingBoards, setLoadingBoards] = React.useState(true);
    const [active, setActive] = React.useState<string>(lastBoard || '');
    const [stored, setStored] = React.useState<{ name: string; query: string }[]>([]);
    const [allTags, setAllTags] = React.useState<string[]>([]);

    const [cards, setCards] = React.useState<Card[]>([]);
    // Refile, copy and archive, through the dialog the search tab and the file
    // view use. A card in the wrong column is often a heading in the wrong
    // file, and having to leave the board to move it is the long way round.
    const [moveOpen, setMoveOpen] = React.useState(false);
    const [moveOp, setMoveOp] = React.useState<MoveOp>('refile');
    const [moveNodes, setMoveNodes] = React.useState<MoveNode[]>([]);
    // The keywords this server accepts. Asked for once: they come from the
    // server's own config, not from any one file, and a board with no columns
    // of its own is built out of them.
    const [todoStates, setTodoStates] = React.useState<{ Active: string[]; Done: string[] }>(
        { Active: [], Done: [] },
    );
    React.useEffect(() => {
        let alive = true;
        ODb.todoStates()
            .then(r => { if (alive && r) setTodoStates({ Active: r.Active || [], Done: r.Done || [] }); })
            .catch(() => { /* a board can still be configured by hand */ });
        return () => { alive = false; };
    }, []);
    const [loadingCards, setLoadingCards] = React.useState(false);
    const [message, setMessage] = React.useState('');
    const [filter, setFilter] = React.useState('');
    const [flipped, setFlipped] = React.useState<Set<string>>(new Set());
    const [settingsOpen, setSettingsOpen] = React.useState(false);
    const [clockedHash, setClockedHash] = React.useState('');
    const [busy, setBusy] = React.useState(false);

    const [drag, setDrag] = React.useState<{ card: Card; from: string } | null>(null);
    const [dropAt, setDropAt] = React.useState<{ col: string; index: number } | null>(null);

    const board = React.useMemo(
        () => boards.find(b => b.name === active) || boards[0] || null,
        [boards, active],
    );

    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';

    // --- loading -----------------------------------------------------------

    const loadBoards = React.useCallback(async () => {
        setLoadingBoards(true);
        const [raw, sq, tags] = await Promise.all([
            ODb.getKanbanBoards(),
            ODb.getStoredQueries(),
            ODb.getAllTags(),
        ]);
        const list = (raw || []).map(normalizeBoard);
        setBoards(list);
        setStored(sq || []);
        setAllTags(tags || []);
        setActive(a => (list.some(b => b.name === a) ? a : (list.length > 0 ? list[0].name : '')));
        setLoadingBoards(false);
    }, []);

    React.useEffect(() => { loadBoards(); }, [loadBoards]);

    // Which board was open is remembered for this browser only.
    React.useEffect(() => {
        if (active && active !== lastBoard) setLastBoard(active);
    }, [active, lastBoard, setLastBoard]);

    const hasBoard = !!board;
    const queryKey = board ? `${board.storedQuery} ${board.query} ${board.includeArchived}` : '';

    // Re-reads the board and answers with what the query found, so a caller
    // that has just moved a card can see whether it is still there.
    const refresh = React.useCallback(async (signal?: AbortSignal): Promise<Card[] | null> => {
        if (!board) { setCards([]); return null; }
        const { query, baseFilter } = boardQuery(board, stored);
        // What is written under a heading is read separately and cached by
        // hash, and a hash does not change when the text does - so reading the
        // board back means reading the bodies back too, or a card keeps the
        // checklist it had before somebody edited the file.
        forgetAllBodies();
        setLoadingCards(true);
        const controller = signal ? null : new AbortController();
        const sig = signal || controller!.signal;
        try {
            const res = await ODb.query(query, false, sig, baseFilter);
            if (sig.aborted) return null;
            const list = Array.isArray(res) ? (res as Card[]) : [];
            setCards(list);
            setMessage('');
            return list;
        } catch {
            if (!sig.aborted) { setCards([]); setMessage('Could not run that board’s query.'); }
            return null;
        } finally {
            if (!sig.aborted) setLoadingCards(false);
        }
    }, [board, stored]);

    // The query is what decides the cards; the rest of a board's settings only
    // decide how they are drawn, so the cards are re-read when the query
    // changes and not when a colour does - which would otherwise be a round
    // trip per keystroke in the settings dialog. refresh is held in a ref and
    // kept out of the list for that same reason: it closes over the whole
    // board, colours and all.
    const refreshRef = React.useRef(refresh);
    refreshRef.current = refresh;
    React.useEffect(() => {
        if (!hasBoard) { setCards([]); return; }
        const controller = new AbortController();
        refreshRef.current(controller.signal);
        return () => controller.abort();
    }, [hasBoard, queryKey, stored]);

    // A drag that ends anywhere - on a column, on the gap between two of them,
    // outside the window entirely - puts the board back. Without this a drag
    // let go over nothing leaves the card it picked up faded and the board
    // waiting for a drop that is never coming.
    React.useEffect(() => {
        if (!drag) return;
        const done = () => { setDrag(null); setDropAt(null); };
        window.addEventListener('dragend', done);
        window.addEventListener('drop', done);
        return () => {
            window.removeEventListener('dragend', done);
            window.removeEventListener('drop', done);
        };
    }, [drag]);

    // The heading the clock is running on, so a card can offer to stop it.
    const readClock = React.useCallback(async () => {
        try {
            const st: any = await ODb.getClockState();
            setClockedHash(st && st.Active && st.Target ? (st.Target.Hash || '') : '');
        } catch { /* a server with no clock running is not an error worth showing */ }
    }, []);
    React.useEffect(() => { readClock(); }, [readClock]);

    // --- board writes ------------------------------------------------------

    const saveBoards = React.useCallback(async (next: KanbanBoard[]) => {
        setBoards(next);
        const res = await ODb.saveKanbanBoards(next);
        if (res && res.Ok === false) setMessage(res.Msg || 'Could not save the boards.');
    }, []);

    function addBoard() {
        const name = uniqueName('Board', boards.map(b => b.name));
        const b = newBoard(name);
        const next = [...boards, b];
        saveBoards(next);
        setActive(name);
        setSettingsOpen(true);
    }

    function onSaveBoard(next: KanbanBoard, originalName: string) {
        const list = boards.map(b => (b.name === originalName ? next : b));
        saveBoards(list);
        setActive(next.name);
        setSettingsOpen(false);
    }

    function onDeleteBoard(name: string) {
        const list = boards.filter(b => b.name !== name);
        saveBoards(list);
        setActive(list.length > 0 ? list[0].name : '');
        setSettingsOpen(false);
    }

    function onDuplicateBoard(b: KanbanBoard) {
        const name = uniqueName(`${b.name} copy`, boards.map(x => x.name));
        const copy = { ...b, name };
        saveBoards([...boards, copy]);
        setActive(name);
        setSettingsOpen(false);
    }

    // Which columns are folded away. The board itself is the only copy, which
    // is what makes it survive a reload - and it has to live on the *board*
    // rather than on its columns, because a board that reads its columns off
    // the server's todo keywords has no stored column to write a flag on (the
    // old code mapped over an empty list and folding silently did nothing),
    // and the catch-all column is appended rather than stored, so it has
    // nowhere of its own either.
    const folded = React.useMemo(() => new Set(board?.folded || []), [board]);

    // Writing the list back is the whole of remembering it: saveBoards puts the
    // boards on screen straight away and posts them, the same as any other
    // board edit.
    const setFoldedValues = React.useCallback((values: string[]) => {
        if (!board) return;
        saveBoards(boards.map(b => (b.name !== board.name ? b : { ...b, folded: values })));
    }, [board, boards, saveBoards]);

    const setCollapsed = React.useCallback((value: string, collapsed: boolean) => {
        if (!board) return;
        const now = board.folded || [];
        if (collapsed) {
            if (now.indexOf(value) >= 0) return;
            setFoldedValues([...now, value]);
        } else {
            setFoldedValues(now.filter(v => v !== value));
        }
    }, [board, setFoldedValues]);

    const collapseAll = React.useCallback((collapsed: boolean) => {
        if (!board) return;
        // Folding everything names every column on show. Opening everything
        // clears the list outright rather than subtracting them, so a value
        // left behind by a column the query no longer turns up cannot keep the
        // Open all button looking like it did nothing.
        setFoldedValues(collapsed ? columnsRef.current.map(c => c.value) : []);
    }, [board, setFoldedValues]);

    // Write the columns the board is currently showing into the board, so they
    // can be renamed, recoloured and reordered. Until this is pressed they are
    // worked out fresh every time and keep up with the server's states and the
    // query; after it they are the board's own and stop moving.
    function adoptDerivedColumns() {
        if (!board || derived.length === 0) return;
        const next = boards.map(b => (b.name !== board.name ? b : { ...b, columns: derived }));
        saveBoards(next);
    }

    function fillColumnsFromCards() {
        if (!board) return;
        const found = discoverValues(cards, board);
        if (found.length === 0) return;
        const next = boards.map(b => (b.name !== board.name ? b : {
            ...b,
            columns: [...b.columns, ...found.map(v => ({ value: v, title: '', color: '', limit: 0, collapsed: false }))],
        }));
        saveBoards(next);
    }

    // --- layout ------------------------------------------------------------

    const terms = React.useMemo(() => searchTerms(filter), [filter]);

    // A board split by keyword and told nothing about its columns reads them off
    // the server's configured states, plus any the query turned up that the
    // configuration never mentioned. Worked out rather than written into the
    // board, so it keeps up with both as they change - the moment the board is
    // given columns of its own, those win.
    const derived: KanbanColumn[] = React.useMemo(() => {
        if (!board || board.columns.length > 0 || board.groupBy !== 'status') return [];
        return defaultStatusColumns(
            { active: todoStates.Active, done: todoStates.Done },
            statusesInCards(cards),
        );
    }, [board, todoStates, cards]);

    // Every column of the board plus, when it is asked for, the one that
    // catches whatever no column claimed. That last one is appended rather than
    // stored, so turning it off and on again cannot lose a configured column.
    const columns: KanbanColumn[] = React.useMemo(() => {
        if (!board) return [];
        // A board split by keyword and told nothing about its columns reads
        // them off the server's configured states, plus any the query turned up
        // that the configuration never mentioned. Worked out here rather than
        // written into the board, so it keeps up with both as they change -
        // the moment the board is given columns of its own, those win.
        const cols = derived.length > 0 ? derived.slice() : board.columns.slice();
        // The catch-all goes on the **far left**, always: it is where a card
        // with nothing said about it sits, which is before the work starts
        // rather than after it has finished. Still appended rather than stored,
        // so turning it off and on again cannot lose a configured column.
        if (board.showUnset) cols.unshift(unsetColumn(board));
        return cols.map(c => ({ ...c, collapsed: folded.has(c.value) }));
    }, [board, derived, folded]);

    // The sections actually drawn in the list. Hiding is a list idea - the
    // board's columns are already scrollable and putting one away there would
    // just be a narrower board - so the columns themselves are left whole and
    // the list is handed the shorter list. Buckets are still built from every
    // column, which is what lets the restore menu say how many rows are in a
    // section nobody can see.
    const shownColumns = React.useMemo(() => {
        const away = new Set(board?.hidden || []);
        if (away.size === 0) return columns;
        return columns.filter(c => !away.has(c.value));
    }, [columns, board]);

    // collapseAll needs the columns and the columns need nothing from it, so
    // the list is read through a ref rather than the two being tangled.
    const columnsRef = React.useRef<KanbanColumn[]>([]);
    columnsRef.current = columns;

    const buckets = React.useMemo(() => {
        const out = new Map<string, Card[]>();
        if (!board) return out;
        for (const col of columns) out.set(col.value, []);
        for (const c of cards) {
            const value = columnOf(c, board, columns);
            const list = out.get(value);
            if (list) list.push(c);
        }
        const sorted = new Map<string, Card[]>();
        out.forEach((list, key) => sorted.set(key, sortCards(list, board)));
        return sorted;
    }, [cards, columns, board]);

    // Cards the query found that no column on the board wanted. Worth saying
    // out loud: a board quietly showing two thirds of its query looks like a
    // board with fewer cards on it, not like a board missing a column.
    const homeless = React.useMemo(() => {
        if (!board) return 0;
        let n = 0;
        const have = new Set(columns.map(c => c.value));
        for (const c of cards) if (!have.has(columnOf(c, board, columns))) n++;
        return n;
    }, [cards, columns, board]);

    const matched = React.useMemo(
        () => (terms.length === 0 ? cards.length : cards.filter(c => cardMatches(c, terms)).length),
        [cards, terms],
    );

    // Dropping into the catch-all column means taking the value away, and there
    // is one case where that cannot be done: org has no way to spell a heading
    // with no todo keyword through this endpoint, so the board refuses the drop
    // rather than writing something the server will reject.
    const dropRefusedFor = React.useCallback((value: string): boolean => {
        return !!board && board.groupBy === 'status' && value === UNSET;
    }, [board]);

    // --- moving a card -----------------------------------------------------

    // The order value the moved card needs to land where it was dropped, and
    // the renumbering to fall back on when the gap it was dropped into has run
    // out of room. Only the card that moved is written in the ordinary case.
    function planOrder(target: string, index: number, moving: Card): { writes: { card: Card; value: number }[] } | null {
        if (!board || board.sort !== 'manual') return null;
        const list = (buckets.get(target) || []).filter(c => c.Hash !== moving.Hash);
        const at = Math.max(0, Math.min(index, list.length));
        const prev = at > 0 ? list[at - 1] : null;
        const next = at < list.length ? list[at] : null;
        const prevOrder = prev ? orderOf(prev, board) : null;
        const nextOrder = next ? orderOf(next, board) : null;

        // A card sitting above the drop with no order of its own has nothing to
        // be above: the whole column is renumbered rather than guessed at.
        if (!(prev && prevOrder === null)) {
            const value = orderBetween(prevOrder, nextOrder);
            if (value !== null) return { writes: [{ card: moving, value }] };
        }
        const after = list.slice();
        after.splice(at, 0, moving);
        const numbers = renumber(after.length);
        const writes: { card: Card; value: number }[] = [];
        after.forEach((c, i) => {
            if (c.Hash === moving.Hash || orderOf(c, board) !== numbers[i]) writes.push({ card: c, value: numbers[i] });
        });
        return { writes };
    }

    async function moveCard(card: Card, from: string, target: string, index: number) {
        if (!board) return;
        if (dropRefusedFor(target)) {
            setMessage('A heading cannot have its todo keyword taken away from here.');
            return;
        }
        setBusy(true);
        setMessage('');

        const order = planOrder(target, index, card);

        // The board moves the card at once and asks afterwards. A write that
        // fails puts the message up and refreshes, which reads the truth back
        // off the server rather than leaving a card somewhere it is not.
        const optimistic = (c: Card): Card => {
            if (c.Hash !== card.Hash) return c;
            const next: Card = { ...c, Props: { ...(c.Props || {}) }, Tags: (c.Tags || []).slice() };
            if (from !== target) {
                if (board.groupBy === 'property') next.Props![board.groupKey] = target;
                else if (board.groupBy === 'status') next.Status = target;
                else if (board.groupBy === 'tag') {
                    next.Tags = next.Tags!.filter(t => t !== from);
                    if (target !== UNSET) next.Tags!.push(target);
                }
            }
            return next;
        };
        setCards(cs => cs.map(c => {
            let out = optimistic(c);
            if (order) {
                const w = order.writes.find(x => x.card.Hash === c.Hash);
                if (w) out = { ...out, Props: { ...(out.Props || {}), [board.orderKey || 'KANBAN']: formatOrder(w.value) } };
            }
            return out;
        }));

        let failed = '';
        try {
            if (from !== target) {
                if (board.groupBy === 'property') {
                    const res: any = await ODb.changeProperty(card.Hash, board.groupKey, target);
                    if (res && res.Ok === false) failed = `Could not set ${board.groupKey}.`;
                } else if (board.groupBy === 'status') {
                    const res: any = await ODb.changeStatus(card.Hash, target);
                    if (!res || res.Ok === false) failed = `${target} is not a todo keyword that file allows.`;
                } else if (board.groupBy === 'tag') {
                    if (from !== UNSET) await ODb.toggleTag(card.Hash, from);
                    if (target !== UNSET) await ODb.toggleTag(card.Hash, target);
                }
            }
            if (!failed && order) {
                const key = board.orderKey || 'KANBAN';
                for (const w of order.writes) {
                    await ODb.changeProperty(w.card.Hash, key, formatOrder(w.value));
                }
            }
        } catch {
            failed = 'The server did not take that move.';
        }

        if (failed) setMessage(failed);
        setBusy(false);
        // Either way the board reads itself back: the hash of a heading whose
        // keyword changed is not the hash it had, and a stale one cannot be
        // dragged again.
        const after = await refresh();

        // A card can be moved correctly and still leave the board, because the
        // board's query decides what is on it and the move may have just made
        // the card stop matching - dropping something into DONE on a board
        // whose query is IsTodo() is the common way. The write worked; saying
        // nothing makes it look as though the card was lost.
        if (!failed && after && from !== target) {
            const still = after.some(c => c.Headline === card.Headline && c.Filename === card.Filename);
            if (!still) {
                setMessage(
                    `“${card.Headline}” is now ${target === UNSET ? 'unset' : target}`
                    + ` and no longer matches this board’s query, so it has left the board.`
                    + ` It is still in ${(card.Filename || '').split('/').pop() || 'its file'}.`,
                );
            }
        }
    }

    async function onAct(what: CardAction, card: Card) {
        // The three that move a heading go through the shared dialog rather
        // than straight at the server. Archive used to fire on the click with
        // no confirmation and no way to see what it did; the other two need
        // somewhere to go, and all three want to say what happened.
        if (what === 'archive' || what === 'refile' || what === 'copy') {
            setMoveOp(what);
            setMoveNodes([{ hash: card.Hash, headline: card.Headline, filename: card.Filename }]);
            setMoveOpen(true);
            return;
        }
        setBusy(true);
        try {
            if (what === 'clockin') { await ODb.clockIn(card.Hash); setClockedHash(card.Hash); }
            else { await ODb.clockOut(); setClockedHash(''); }
        } catch {
            setMessage('That did not go through.');
        }
        setBusy(false);
        readClock();
    }

    // Setting a keyword from the list. On a board split by keyword this is a
    // move between sections, so it goes through the same path a drag does -
    // which is what keeps the ordering, the optimistic update and the "it has
    // left the board" message. On any other board the keyword is just a field
    // of the heading and nothing about the layout changes.
    async function setCardStatus(card: Card, status: string) {
        if (!board) return;
        if (board.groupBy === 'status') {
            const from = columnOf(card, board, columns);
            if (from === status) return;
            await moveCard(card, from, status, (buckets.get(status) || []).length);
            return;
        }
        setBusy(true);
        setMessage('');
        setCards(cs => cs.map(c => (c.Hash === card.Hash ? { ...c, Status: status } : c)));
        try {
            const res: any = await ODb.changeStatus(card.Hash, status);
            if (!res || res.Ok === false) setMessage(`${status} is not a todo keyword that file allows.`);
        } catch {
            setMessage('The server did not take that change.');
        }
        setBusy(false);
        refresh();
    }

    // Moving a section up or down. The order of the sections is the order of
    // the board's columns, so a board that was reading its columns off the
    // server's keywords takes them as its own here - which is what ordering
    // them means, and the alert above the list says as much.
    function moveSection(value: string, by: number) {
        if (!board || value === UNSET) return;
        const cols = (board.columns.length > 0 ? board.columns : derived).slice();
        const i = cols.findIndex(c => c.value === value);
        const j = i + by;
        if (i < 0 || j < 0 || j >= cols.length) return;
        const tmp = cols[i];
        cols[i] = cols[j];
        cols[j] = tmp;
        saveBoards(boards.map(b => (b.name !== board.name ? b : { ...b, columns: cols })));
    }

    // What the card menus offer: the board's own set plus anything the cards
    // are already wearing, so a tag added in the editor can be taken off here.
    const labelChoices = React.useMemo(
        () => (board ? labelsInCards(cards, board) : []),
        [cards, board],
    );

    // Putting a label on a heading, or taking it off. Tags toggle; a property
    // holds the list, so it is rewritten with the value added or removed - and
    // emptied to nothing rather than left as a stray comma.
    async function toggleLabel(card: Card, value: string) {
        if (!board || board.labelSource === 'none') return;
        const on = labelsOf(card, board).indexOf(value) >= 0;
        setBusy(true);
        setMessage('');

        // On screen at once; the refresh underneath says what really happened.
        setCards(cs => cs.map(c => {
            if (c.Hash !== card.Hash) return c;
            if (board.labelSource === 'tags') {
                const tags = (c.Tags || []).filter(t => t !== value);
                return { ...c, Tags: on ? tags : [...tags, value] };
            }
            const key = (board.labelKey || '').toUpperCase();
            const now = splitLabels((c.Props || {})[key] || '').filter(v => v !== value);
            const next = on ? now : [...now, value];
            return { ...c, Props: { ...(c.Props || {}), [key]: next.join(' ') } };
        }));

        try {
            if (board.labelSource === 'tags') {
                await ODb.toggleTag(card.Hash, value);
            } else {
                const key = (board.labelKey || '').toUpperCase();
                const now = splitLabels((card.Props || {})[key] || '').filter(v => v !== value);
                const next = on ? now : [...now, value];
                const res: any = await ODb.changeProperty(card.Hash, key, next.join(' '));
                if (res && res.Ok === false) setMessage(`Could not set ${key}.`);
            }
        } catch {
            setMessage('The server did not take that label.');
        }
        setBusy(false);
        refresh();
    }

    function hideSection(value: string, hidden: boolean) {
        if (!board) return;
        const now = board.hidden || [];
        const next = hidden
            ? (now.indexOf(value) >= 0 ? now : [...now, value])
            : now.filter(v => v !== value);
        saveBoards(boards.map(b => (b.name !== board.name ? b : { ...b, hidden: next })));
    }

    // Where a drop lands. The same in both layouts - which is the point: the
    // list and the board are two ways of pointing at one move.
    //
    // `index` is what the drop itself saw. The columns work it out from the
    // last dragover instead, which is right while the pointer is still over a
    // card and wrong the moment it is not, so anything that can say where it
    // landed says so.
    function onDropIn(value: string, index?: number) {
        const d = drag;
        const at = index !== undefined
            ? index
            : (dropAt && dropAt.col === value ? dropAt.index : (buckets.get(value) || []).length);
        setDrag(null);
        setDropAt(null);
        if (d) moveCard(d.card, d.from, value, at);
    }

    function toggleFlip(hash: string) {
        setFlipped(f => {
            const next = new Set(f);
            if (next.has(hash)) next.delete(hash); else next.add(hash);
            return next;
        });
    }

    // --- render ------------------------------------------------------------

    if (loadingBoards) {
        return <Box sx={{ display: 'flex', justifyContent: 'center', p: 6 }}><CircularProgress /></Box>;
    }

    if (boards.length === 0) {
        return (
            <Sheet variant="soft" sx={{ borderRadius: 'md', p: 6, textAlign: 'center', maxWidth: 560, mx: 'auto', mt: 4 }}>
                <ViewKanbanIcon sx={{ fontSize: 44, color: 'text.tertiary' }} />
                <Typography level="title-lg" sx={{ mt: 1 }}>No boards yet</Typography>
                <Typography level="body-sm" sx={{ color: 'text.secondary', mt: 0.5, mb: 2 }}>
                    A board takes a saved query and lays its headings out in columns, split by a
                    property, a tag or the todo keyword. It writes nothing into your files until
                    you drag a card.
                </Typography>
                <Button startDecorator={<AddIcon />} onClick={addBoard}>New board</Button>
            </Sheet>
        );
    }

    // Two buttons rather than one that changes its mind: with a single column
    // left open, a toggle reads as "fold every column" and has to be pressed
    // twice to open them, which is not what somebody reaching for it wants.
    const anyOpen = columns.some(c => !c.collapsed);
    const anyFolded = columns.some(c => c.collapsed);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, gap: 1 }}>
            {/* Boards */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
                <Tabs
                    size="sm"
                    value={active}
                    onChange={(_, v) => setActive((v as string) || '')}
                    sx={{ bgcolor: 'transparent', minWidth: 0, flex: 1 }}
                >
                    <TabList
                        variant="plain"
                        sx={{
                            '--List-gap': '4px', flexWrap: 'nowrap', overflowX: 'auto', minWidth: 0,
                            '&::-webkit-scrollbar': { height: 4 },
                        }}
                    >
                        {boards.map(b => (
                            <Tab key={b.name} value={b.name} sx={{ flex: 'none', borderRadius: 'sm' }}>
                                {b.name}
                            </Tab>
                        ))}
                    </TabList>
                </Tabs>
                <Tooltip size="sm" title="New board">
                    <IconButton size="sm" variant="soft" onClick={addBoard}><AddIcon fontSize="small" /></IconButton>
                </Tooltip>
            </Box>

            {/* Tools */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <Input
                    size="sm"
                    placeholder="Find a card"
                    value={filter}
                    onChange={e => setFilter(e.target.value)}
                    startDecorator={<SearchIcon fontSize="small" />}
                    sx={{ width: 240 }}
                />
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {terms.length > 0 ? `${matched} of ${cards.length}` : `${cards.length} card${cards.length === 1 ? '' : 's'}`}
                    {board && board.storedQuery ? ` · ${board.storedQuery}` : ''}
                </Typography>
                {(loadingCards || busy) && <CircularProgress size="sm" />}

                <Box sx={{ ml: 'auto', display: 'flex', gap: 0.5 }}>
                    {flipped.size > 0 && (
                        <Tooltip size="sm" title="Turn every card back over">
                            <IconButton size="sm" variant="plain" onClick={() => setFlipped(new Set())}>
                                <FlipIcon fontSize="small" />
                            </IconButton>
                        </Tooltip>
                    )}
                    <Tooltip size="sm" title="Fold every column">
                        <span>
                            <IconButton size="sm" variant="plain" disabled={!anyOpen} onClick={() => collapseAll(true)}>
                                <UnfoldLessIcon fontSize="small" />
                            </IconButton>
                        </span>
                    </Tooltip>
                    <Tooltip size="sm" title="Open every column">
                        <span>
                            <IconButton size="sm" variant="plain" disabled={!anyFolded} onClick={() => collapseAll(false)}>
                                <UnfoldMoreIcon fontSize="small" />
                            </IconButton>
                        </span>
                    </Tooltip>
                    <Tooltip size="sm" title="Run the query again">
                        <IconButton size="sm" variant="plain" onClick={() => refresh()}><RefreshIcon fontSize="small" /></IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="Board settings">
                        <IconButton size="sm" variant="plain" onClick={() => setSettingsOpen(true)}><SettingsIcon fontSize="small" /></IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title={chrome.hidden ? 'Show the title again' : 'Give the board the window'}>
                        <IconButton size="sm" variant="plain" onClick={() => chrome.setHidden(!chrome.hidden)}>
                            {chrome.hidden ? <CloseFullscreenIcon fontSize="small" /> : <OpenInFullIcon fontSize="small" />}
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>

            {message && (
                <Alert size="sm" variant="soft" color="warning" endDecorator={
                    <Button size="sm" variant="plain" color="neutral" onClick={() => setMessage('')}>Dismiss</Button>
                }>
                    {message}
                </Alert>
            )}

            {board && board.columns.length === 0 && derived.length > 0 && (
                <Alert size="sm" variant="soft" color="neutral"
                    endDecorator={
                        <Box sx={{ display: 'flex', gap: 1 }}>
                            <Button size="sm" variant="soft" onClick={adoptDerivedColumns}>
                                Make them this board’s
                            </Button>
                            <Button size="sm" variant="plain" onClick={() => setSettingsOpen(true)}>Settings</Button>
                        </Box>
                    }
                >
                    These columns are the server’s todo keywords, finished states last, plus anything
                    else the query is using. They follow both until you make them this board’s own.
                </Alert>
            )}

            {board && board.columns.length === 0 && derived.length === 0 && (
                <Alert
                    size="sm"
                    variant="soft"
                    color="primary"
                    endDecorator={
                        <Box sx={{ display: 'flex', gap: 1 }}>
                            <Button size="sm" variant="soft" startDecorator={<AutoAwesomeIcon />} onClick={fillColumnsFromCards}>
                                Fill from the cards
                            </Button>
                            <Button size="sm" variant="plain" onClick={() => setSettingsOpen(true)}>Settings</Button>
                        </Box>
                    }
                >
                    This board has no columns. It can read them off whatever the query found.
                </Alert>
            )}

            {homeless > 0 && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {homeless} card{homeless === 1 ? '' : 's'} no column claims
                    {board && !board.showUnset ? ' — turn on the catch-all column in settings to see them.' : '.'}
                </Typography>
            )}

            {/* The list */}
            {board && board.layout === 'list' && (
                <React.Suspense fallback={<Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}><CircularProgress /></Box>}>
                    <KanbanList
                        board={board}
                        columns={shownColumns}
                        allColumns={columns}
                        buckets={buckets}
                        terms={terms}
                        dark={dark}
                        draggingHash={drag ? drag.card.Hash : null}
                        dropAt={dropAt}
                        clockedHash={clockedHash}
                        dropRefusedFor={dropRefusedFor}
                        doneStates={todoStates.Done}
                        onCollapse={setCollapsed}
                        onMoveSection={moveSection}
                        onHideSection={hideSection}
                        onSetStatus={setCardStatus}
                        onDragStart={c => setDrag({ card: c, from: columnOf(c, board, columns) })}
                        onDragEnd={() => { setDrag(null); setDropAt(null); }}
                        onDragOverAt={(value, index) => setDropAt({ col: value, index })}
                        onDrop={onDropIn}
                        onAct={onAct}
                        onSort={sort => saveBoards(boards.map(b => (b.name !== board.name ? b : { ...b, sort })))}
                    />
                </React.Suspense>
            )}

            {/* The board */}
            {board && board.layout !== 'list' && (
            <Box
                sx={{
                    display: 'flex', gap: 1.25, flex: 1, minHeight: 0, overflowX: 'auto', overflowY: 'hidden',
                    pb: 1, alignItems: 'stretch',
                    scrollSnapType: isMobile ? 'x mandatory' : undefined,
                }}
                onDragLeave={e => { if (e.currentTarget === e.target) setDropAt(null); }}
            >
                {board && columns.map(col => (
                    <Column
                        key={col.value || ' unset'}
                        col={col}
                        cards={buckets.get(col.value) || []}
                        board={board}
                        flipped={flipped}
                        terms={terms}
                        dropIndex={dropAt && dropAt.col === col.value ? dropAt.index : null}
                        isDropTarget={!!drag && !!dropAt && dropAt.col === col.value}
                        dropRefused={dropRefusedFor(col.value)}
                        draggingHash={drag ? drag.card.Hash : null}
                        clockedHash={clockedHash}
                        onFlip={toggleFlip}
                        onCollapse={setCollapsed}
                        onDragStart={c => setDrag({ card: c, from: columnOf(c, board, columns) })}
                        onDragEnd={() => { setDrag(null); setDropAt(null); }}
                        onDragOverAt={(value, index) => setDropAt({ col: value, index })}
                        onDrop={onDropIn}
                        onAct={onAct}
                        labelChoices={labelChoices}
                        onToggleLabel={toggleLabel}
                    />
                ))}
                {board && columns.length === 0 && (
                    <Box sx={{ p: 4, color: 'text.tertiary' }}>
                        <Typography level="body-sm">Nothing to show until this board has a column.</Typography>
                    </Box>
                )}
            </Box>
            )}

            {board && settingsOpen && (
                <React.Suspense fallback={null}>
                    <KanbanSettings
                        open={settingsOpen}
                        board={board}
                        boards={boards}
                        stored={stored}
                        cards={cards}
                        allTags={allTags}
                        onClose={() => setSettingsOpen(false)}
                        onSave={onSaveBoard}
                        onDelete={onDeleteBoard}
                        onDuplicate={onDuplicateBoard}
                    />
                </React.Suspense>
            )}

            {/* Refile, copy and archive. Anything that actually moved has left
                the query, so the board is read again - a copy leaves its source
                where it was and changes nothing here, but reading again is
                cheap and being wrong about it is not. */}
            <MoveDialog
                open={moveOpen}
                op={moveOp}
                nodes={moveNodes}
                onClose={() => setMoveOpen(false)}
                onDone={() => refresh()}
            />
        </Box>
    );
}
