// Every source block in the org files, found and read.
//
// The Tables tab does this for tables; this does it for `#+BEGIN_SRC`. The
// difference is what there is to say about one. A table is its contents; a
// source block is code *plus a contract* - what language it is in, what it is
// called, what it takes and what it gives back - and the contract is the part
// you cannot see by grepping for the code.
//
// The part worth drawing carefully is the variables. `:var data=monthly` and
// `:var scale=2` look identical and mean completely different things: one
// names a table further up the file, the other is the number two. The server
// resolves which is which (internal/app/orgs/code.go); here the difference is
// the difference between a chip that says "table monthly · 4 rows × 3 columns"
// and a value printed as it stands. A name that resolves to nothing gets said
// loudest of all, because that is a block that cannot run.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Chip from '@mui/joy/Chip';
import Divider from '@mui/joy/Divider';
import IconButton from '@mui/joy/IconButton';
import CircularProgress from '@mui/joy/CircularProgress';
import Tooltip from '@mui/joy/Tooltip';
import Link from '@mui/joy/Link';

import SearchIcon from '@mui/icons-material/Search';
import CodeIcon from '@mui/icons-material/CodeOutlined';
import TableIcon from '@mui/icons-material/GridOnOutlined';
import ListIcon from '@mui/icons-material/FormatListBulletedOutlined';
import WarningIcon from '@mui/icons-material/ErrorOutlineOutlined';
import OpenInFileIcon from '@mui/icons-material/LaunchOutlined';
import InputIcon from '@mui/icons-material/InputOutlined';
import OutputIcon from '@mui/icons-material/OutputOutlined';
import TuneIcon from '@mui/icons-material/TuneOutlined';
import ArticleIcon from '@mui/icons-material/ArticleOutlined';
import KeyboardArrowRightIcon from '@mui/icons-material/KeyboardArrowRight';

import Button from '@mui/joy/Button';
import Textarea from '@mui/joy/Textarea';

import PlayIcon from '@mui/icons-material/PlayArrowRounded';
import EditIcon from '@mui/icons-material/EditOutlined';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/DeleteOutline';
import LayersIcon from '@mui/icons-material/LayersOutlined';
import FolderIcon from '@mui/icons-material/FolderOpenOutlined';
import ListOffIcon from '@mui/icons-material/ReorderOutlined';

import { ODb } from '../db';
import {
    CodeBlock, CodeLang, CodeVar, CodeArg, CodeResult,
    blockTitle, blockSource, isReference, isBrokenReference, referenceCount,
    referenceText, langHue, baseName,
} from '../code';
import { tablesIn } from '../orgbody';
import OrgSource from './OrgSource';
import OrgTableView from './OrgTableView';
import CodeText from './CodeText';
import { useNav } from '../NavContext';
import { useSetting } from '../useSettings';
import SplitPane from './SplitPane';

// The icon for a thing a variable can point at. A table looks like a table and
// a block looks like code, so the kind is readable before the words are.
function refIcon(kind: string) {
    const sx = { fontSize: 14 };
    switch (kind) {
        case 'table': return <TableIcon sx={sx} />;
        case 'list': return <ListIcon sx={sx} />;
        case 'src': case 'example': return <CodeIcon sx={sx} />;
        case '': return <WarningIcon sx={sx} />;
        default: return <ArticleIcon sx={sx} />;
    }
}

// One variable: what it is called, and what it is.
function VarRow({ v, onOpen }: { v: CodeVar; onOpen: (file: string, line: number, heading?: string) => void }) {
    const broken = isBrokenReference(v);
    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 0.5 }}>
            <Typography
                level="body-xs"
                sx={{ fontFamily: 'monospace', fontWeight: 'lg', minWidth: 92, flexShrink: 0 }}
            >
                {v.Name}
            </Typography>
            <Typography level="body-xs" sx={{ color: 'text.tertiary', flexShrink: 0 }}>=</Typography>
            {isReference(v) ? (
                <>
                    <Chip
                        size="sm"
                        variant="soft"
                        color={broken ? 'danger' : 'primary'}
                        startDecorator={refIcon(v.RefKind)}
                        onClick={broken || !v.RefFile ? undefined : () => onOpen(v.RefFile, v.RefLine)}
                        sx={{ cursor: broken || !v.RefFile ? 'default' : 'pointer' }}
                    >
                        {referenceText(v)}
                    </Chip>
                    {v.Index !== '' && (
                        <Typography level="body-xs" sx={{ fontFamily: 'monospace', color: 'text.tertiary' }}>
                            {v.Index}
                        </Typography>
                    )}
                </>
            ) : (
                <Typography level="body-xs" sx={{ fontFamily: 'monospace' }}>
                    {v.Value === '' ? <em style={{ opacity: 0.6 }}>nothing</em> : v.Value}
                </Typography>
            )}
        </Box>
    );
}

// ── What a run gave back ────────────────────────────────────────────────────

// The result, drawn as the shape it is.
//
// A table goes to OrgTableView - the same viewer the Tables tab uses - by way
// of `tablesIn`, the org table parser this app already has. The server sends
// a table back as *org table text* precisely so that this is possible: one
// format across the wire, one parser, one view, and no second idea of what a
// row is.
function RunResult({ res, onClear }: { res: CodeResult; onClear: () => void }) {
    const [raw, setRaw] = React.useState(false);
    const table = React.useMemo(
        () => (res.Kind === 'table' && !raw ? tablesIn(res.Result)[0] : null), [res, raw]);
    const failed = !res.Ok;

    return (
        <Sheet
            variant="outlined"
            sx={{
                borderRadius: 'sm', mb: 1.5, overflow: 'hidden',
                borderLeft: '3px solid',
                borderLeftColor: failed ? 'danger.500' : 'success.500',
            }}
        >
            <Box sx={{
                display: 'flex', alignItems: 'center', gap: 1, px: 1.25, py: 0.75,
                bgcolor: 'background.level1',
            }}>
                <OutputIcon sx={{ fontSize: 15, color: 'text.tertiary' }} />
                <Typography level="body-xs" sx={{ color: failed ? 'danger.500' : 'text.secondary' }}>
                    {failed ? (res.Msg || 'It did not finish') : `Ran in ${res.Seconds.toFixed(2)}s`}
                </Typography>
                {res.Ok && res.Kind !== 'text' && (
                    <Chip size="sm" variant="soft" color="neutral" sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}>
                        {res.Kind}
                    </Chip>
                )}
                <Box sx={{ flex: 1 }} />
                {/* The shape is a guess when :results did not say, so the text
                    it was guessed from is always one click away. */}
                {res.Kind !== 'text' && res.Raw !== '' && (
                    <Link component="button" level="body-xs" onClick={() => setRaw(v => !v)} sx={{ color: 'text.tertiary' }}>
                        {raw ? 'as a ' + res.Kind : 'as it printed'}
                    </Link>
                )}
                <IconButton size="sm" variant="plain" color="neutral" onClick={onClear} title="Clear">
                    <CloseIcon sx={{ fontSize: 15 }} />
                </IconButton>
            </Box>

            <Box sx={{ p: 1.25, maxHeight: 320, overflow: 'auto' }}>
                {res.Msg !== '' && failed && res.Stderr === '' && (
                    <Typography level="body-sm" sx={{ whiteSpace: 'pre-wrap' }}>{res.Msg}</Typography>
                )}
                {table ? (
                    <OrgTableView table={table} />
                ) : res.Kind === 'list' && !raw ? (
                    <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
                        {res.Result.split('\n').map((l, i) => (
                            <Typography key={i} component="li" level="body-sm">
                                {l.replace(/^\s*-\s*/, '')}
                            </Typography>
                        ))}
                    </Box>
                ) : res.Kind === 'file' && !raw ? (
                    <FileResult res={res} />
                ) : (res.Raw !== '' || res.Result !== '') ? (
                    <Typography
                        level="body-xs"
                        sx={{ fontFamily: 'monospace', whiteSpace: 'pre', fontSize: 12 }}
                    >
                        {raw ? res.Raw : (res.Result || res.Raw)}
                    </Typography>
                ) : !failed ? (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                        It printed nothing.
                    </Typography>
                ) : null}

                {/* Shown on success as well as failure: plenty of programs
                    warn and still work, and a warning nobody sees is a warning
                    that was not given. */}
                {res.Stderr !== '' && (
                    <Box sx={{ mt: res.Result || res.Raw ? 1.25 : 0 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>
                            standard error
                        </Typography>
                        <Typography
                            level="body-xs"
                            sx={{
                                fontFamily: 'monospace', whiteSpace: 'pre', fontSize: 11,
                                color: failed ? 'danger.500' : 'warning.500',
                            }}
                        >
                            {res.Stderr}
                        </Typography>
                    </Box>
                )}
            </Box>
        </Sheet>
    );
}

function prettyBytes(n: number): string {
    if (n < 1024) return `${n} B`;
    if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} kB`;
    return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

// A `:results file` result: the link the block gave back, and then the file
// itself.
//
// The link on its own is half an answer - a block whose result is a filename
// has produced something, and the something is what you wanted to see. So it
// comes in two boxes: what the block said, and what it made. Which the second
// box is depends on what the file is, and the server decided that (one list of
// what counts as an image, shared with the exporter that needed it first).
function FileResult({ res }: { res: CodeResult }) {
    const name = res.File || res.Result;
    const missing = res.File !== '' && !res.Exists;

    return (
        <Box>
            {/* What the block said. */}
            <Typography level="body-sm" sx={{ fontFamily: 'monospace' }}>{res.Result}</Typography>

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5, mb: 1, flexWrap: 'wrap' }}>
                {missing ? (
                    <Typography level="body-xs" color="danger">
                        Nothing is at that path — the block named a file it did not write.
                    </Typography>
                ) : res.Exists ? (
                    <>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {prettyBytes(res.Bytes)}
                            {res.TextLang !== '' && ` · ${res.TextLang}`}
                            {res.Truncated && ' · showing the first part'}
                        </Typography>
                        {res.Url !== '' && (
                            <Link
                                level="body-xs"
                                href={res.Url}
                                target="_blank"
                                rel="noreferrer"
                                sx={{ color: 'text.tertiary' }}
                            >
                                open it
                            </Link>
                        )}
                    </>
                ) : null}
            </Box>

            {/* What it made. */}
            {res.Exists && res.Media === 'image' && res.Url !== '' && (
                <Box
                    component="img"
                    src={res.Url}
                    alt={name}
                    sx={{
                        maxWidth: '100%', borderRadius: 'sm', display: 'block',
                        boxShadow: 'inset 0 0 0 1px var(--joy-palette-divider)',
                    }}
                />
            )}
            {res.Exists && res.Media === 'audio' && res.Url !== '' && (
                <Box
                    component="audio"
                    src={res.Url}
                    controls
                    preload="none"
                    sx={{ width: '100%', height: 36, colorScheme: 'light dark' }}
                />
            )}
            {res.Exists && res.Media === 'video' && res.Url !== '' && (
                <Box
                    component="video"
                    src={res.Url}
                    controls
                    preload="metadata"
                    sx={{ maxWidth: '100%', borderRadius: 'sm', display: 'block' }}
                />
            )}
            {res.Exists && res.Media === 'pdf' && res.Url !== '' && (
                <Box
                    component="iframe"
                    src={res.Url}
                    title={name}
                    sx={{ width: '100%', height: 420, border: 0, borderRadius: 'sm' }}
                />
            )}
            {res.Exists && res.Media === 'text' && res.Text !== '' && (
                res.TextLang === 'org'
                    ? (
                        <Sheet variant="outlined" sx={{ borderRadius: 'sm', maxHeight: 360, overflow: 'auto' }}>
                            <OrgSource text={res.Text} wrap openDrawers />
                        </Sheet>
                    )
                    : <CodeText text={res.Text} lang={res.TextLang} maxHeight={360} />
            )}
            {res.Exists && res.Media === 'binary' && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                    Not something to read here — open it instead.
                </Typography>
            )}
        </Box>
    );
}

// ── Editing one ─────────────────────────────────────────────────────────────

// A row of key/value pairs with a remove button and a way to add one, used for
// the header arguments and again for the variables.
function PairRows({ rows, keyLabel, valueLabel, onChange, mono }: {
    rows: { k: string; v: string }[];
    keyLabel: string;
    valueLabel: string;
    onChange: (rows: { k: string; v: string }[]) => void;
    mono?: boolean;
}) {
    const set = (i: number, patch: Partial<{ k: string; v: string }>) =>
        onChange(rows.map((r, j) => (j === i ? { ...r, ...patch } : r)));
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
            {rows.map((r, i) => (
                <Box key={i} sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                    <Input
                        size="sm" placeholder={keyLabel} value={r.k}
                        onChange={e => set(i, { k: e.target.value })}
                        sx={{ width: 150, flexShrink: 0, '& input': { fontFamily: 'monospace', fontSize: 12 } }}
                    />
                    <Input
                        size="sm" placeholder={valueLabel} value={r.v}
                        onChange={e => set(i, { v: e.target.value })}
                        sx={{ flex: 1, ...(mono ? { '& input': { fontFamily: 'monospace', fontSize: 12 } } : {}) }}
                    />
                    <IconButton
                        size="sm" variant="plain" color="danger"
                        onClick={() => onChange(rows.filter((_, j) => j !== i))}
                    >
                        <DeleteIcon sx={{ fontSize: 16 }} />
                    </IconButton>
                </Box>
            ))}
            <Button
                size="sm" variant="plain" color="neutral" startDecorator={<AddIcon />}
                onClick={() => onChange([...rows, { k: '', v: '' }])}
                sx={{ alignSelf: 'flex-start' }}
            >
                Another
            </Button>
        </Box>
    );
}

function BlockEditor({ block, onSaved, onCancel, onRun }: {
    block: CodeBlock;
    onSaved: () => void;
    onCancel: () => void;
    onRun: (code: string) => void;
}) {
    const hue = langHue(block.Lang);
    const [name, setName] = React.useState(block.Name);
    const [lang, setLang] = React.useState(block.Lang);
    const [switches, setSwitches] = React.useState((block.Switches || []).join(' '));
    const [code, setCode] = React.useState(block.Code);
    const [vars, setVars] = React.useState(
        (block.Vars || []).map(v => ({ k: v.Name, v: v.Value })));
    const [args, setArgs] = React.useState(
        (block.Args || []).map(a => ({ k: a.Key, v: a.Value })));
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');

    const save = async () => {
        setBusy(true);
        setError('');
        try {
            const res = await ODb.updateCode({
                Filename: block.Filename,
                Id: block.Id,
                Name: name.trim(), SetName: true,
                Lang: lang.trim(),
                Switches: switches.split(/\s+/).filter(Boolean),
                Vars: vars.filter(r => r.k.trim()).map(r => ({
                    Name: r.k.trim(), Value: r.v.trim(),
                    Ref: '', RefKind: '', RefFile: '', RefLine: 0, Rows: 0, Cols: 0, Index: '',
                })) as CodeVar[],
                Args: args.filter(r => r.k.trim()).map(r => ({ Key: r.k.trim(), Value: r.v.trim() })) as CodeArg[],
                SetHeader: true,
                Code: code, SetCode: true,
            });
            if (!res || res.Ok === false) { setError((res && res.Msg) || 'The server would not write that.'); setBusy(false); return; }
            onSaved();
        } catch (e: any) {
            setError(e?.message || 'That did not go through.');
            setBusy(false);
        }
    };

    // The preview of the header line, so the thing being edited by form can be
    // checked as the org it will become.
    const preview = blockSource(
        {
            ...block, Name: name, Lang: lang,
            Switches: switches.split(/\s+/).filter(Boolean),
            Vars: vars.filter(r => r.k.trim()).map(r => ({ Name: r.k, Value: r.v } as CodeVar)),
            Args: args.filter(r => r.k.trim()).map(r => ({ Key: r.k, Value: r.v })),
        },
        '');

    return (
        <Box sx={{ p: 2.5, overflowY: 'auto', height: '100%' }}>
            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', mb: 1.5 }}>
                <Typography level="title-md">Editing</Typography>
                <Box sx={{ flex: 1 }} />
                <Button size="sm" onClick={save} loading={busy} startDecorator={<CheckIcon />}>Save</Button>
                <Button
                    size="sm" variant="soft" color="neutral"
                    startDecorator={<PlayIcon />} onClick={() => onRun(code)}
                >
                    Try it
                </Button>
                <Button size="sm" variant="plain" color="neutral" onClick={onCancel} startDecorator={<CloseIcon />}>
                    Cancel
                </Button>
            </Box>

            <Box sx={{ display: 'flex', gap: 1, mb: 1.25 }}>
                <Box sx={{ flex: 2 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>
                        Name — what another block calls it by
                    </Typography>
                    <Input
                        size="sm" placeholder="unnamed" value={name}
                        onChange={e => setName(e.target.value)}
                        sx={{ '& input': { fontFamily: 'monospace' } }}
                    />
                </Box>
                <Box sx={{ flex: 1 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>Language</Typography>
                    <Input
                        size="sm" value={lang} onChange={e => setLang(e.target.value)}
                        sx={{ '& input': { fontFamily: 'monospace' } }}
                    />
                </Box>
                <Box sx={{ flex: 1 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>Switches</Typography>
                    <Input
                        size="sm" placeholder="-n -r" value={switches}
                        onChange={e => setSwitches(e.target.value)}
                        sx={{ '& input': { fontFamily: 'monospace' } }}
                    />
                </Box>
            </Box>

            <Typography
                level="body-xs" startDecorator={<InputIcon sx={{ fontSize: 15 }} />}
                sx={{ color: 'text.tertiary', mb: 0.5 }}
            >
                Variables — a value, or the name of a table or block in the same file
            </Typography>
            <Box sx={{ mb: 1.25 }}>
                <PairRows rows={vars} keyLabel="name" valueLabel="value or name" mono onChange={setVars} />
            </Box>

            <Typography
                level="body-xs" startDecorator={<TuneIcon sx={{ fontSize: 15 }} />}
                sx={{ color: 'text.tertiary', mb: 0.5 }}
            >
                Header arguments — :results, :exports, :tangle, :dir…
            </Typography>
            <Box sx={{ mb: 1.25 }}>
                <PairRows rows={args} keyLabel=":key" valueLabel="value" mono onChange={setArgs} />
            </Box>

            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>Code</Typography>
            <Textarea
                minRows={8}
                maxRows={26}
                value={code}
                onChange={e => setCode(e.target.value)}
                sx={{
                    mb: 1.25, fontFamily: 'monospace', fontSize: 13,
                    '--Textarea-focusedHighlight': `hsl(${hue} 70% 55%)`,
                    '& textarea': { whiteSpace: 'pre', overflowX: 'auto' },
                }}
            />

            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>Written as</Typography>
            <Sheet
                variant="outlined"
                sx={{
                    borderRadius: 'sm', mb: 1.5, overflow: 'auto',
                    borderLeft: '3px solid', borderLeftColor: `hsl(${hue} 70% 55%)`,
                }}
            >
                <OrgSource text={preview} wrap openDrawers />
            </Sheet>

            {error !== '' && <Typography level="body-sm" color="danger">{error}</Typography>}
        </Box>
    );
}

// ── One block, in full ──────────────────────────────────────────────────────

function BlockCard({ block, onOpen, onRun, onEdit, running, result, onClearResult }: {
    block: CodeBlock;
    onOpen: (file: string, line: number, heading?: string, from?: CodeBlock) => void;
    onRun: () => void;
    onEdit: () => void;
    running: boolean;
    result: CodeResult | null;
    onClearResult: () => void;
}) {
    const hue = langHue(block.Lang);
    const vars = block.Vars || [];
    const args = block.Args || [];
    const switches = block.Switches || [];
    const takes = vars.filter(isReference);

    return (
        <Box sx={{ p: 2.5, overflowY: 'auto', height: '100%' }}>
            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1.5, mb: 2 }}>
                <Box sx={{ minWidth: 0, flex: 1 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                        <Typography level="h3" sx={{ fontSize: 22, lineHeight: 1.2 }}>
                            {blockTitle(block)}
                        </Typography>
                        <Chip
                            size="sm"
                            variant="soft"
                            sx={{
                                fontFamily: 'monospace',
                                color: `hsl(${hue} 55% 35%)`,
                                background: `hsl(${hue} 65% 92%)`,
                                '[data-joy-color-scheme="dark"] &': {
                                    color: `hsl(${hue} 70% 80%)`,
                                    background: `hsl(${hue} 32% 26%)`,
                                },
                            }}
                        >
                            {block.Lang || 'no language'}
                        </Chip>
                        {block.Name === '' && (
                            <Tooltip size="sm" title="Without a #+NAME: nothing else can call this block">
                                <Chip size="sm" variant="outlined" color="neutral">unnamed</Chip>
                            </Tooltip>
                        )}
                    </Box>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 0.25 }}>
                        {(block.Olp || []).join(' › ') || 'above the first heading'}
                    </Typography>
                </Box>
                <Button
                    size="sm"
                    color="success"
                    variant="soft"
                    loading={running}
                    startDecorator={<PlayIcon />}
                    onClick={onRun}
                >
                    Run
                </Button>
                <Tooltip size="sm" title="Edit it">
                    <IconButton size="sm" variant="outlined" color="neutral" onClick={onEdit}>
                        <EditIcon sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
                <Tooltip size="sm" title="Open it in Files">
                    <IconButton
                        size="sm"
                        variant="outlined"
                        color="neutral"
                        onClick={() => onOpen(block.Filename, block.Line, (block.Olp || []).slice(-1)[0], block)}
                    >
                        <OpenInFileIcon sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
            </Box>

            {/* What it takes. First, because it is the thing you cannot see by
                reading the code. */}
            {vars.length > 0 && (
                <Sheet variant="soft" sx={{ borderRadius: 'md', px: 1.75, py: 1, mb: 1.5 }}>
                    <Typography
                        level="body-xs"
                        startDecorator={<InputIcon sx={{ fontSize: 15 }} />}
                        sx={{ color: 'text.tertiary', mb: 0.5 }}
                    >
                        Takes{takes.length > 0 && ` — ${takes.length} from the file`}
                    </Typography>
                    {vars.map((v, i) => (
                        <VarRow key={v.Name + i} v={v} onOpen={(f, l) => onOpen(f, l, undefined, block)} />
                    ))}
                </Sheet>
            )}

            {(args.length > 0 || switches.length > 0) && (
                <Box sx={{ mb: 1.5 }}>
                    <Typography
                        level="body-xs"
                        startDecorator={<TuneIcon sx={{ fontSize: 15 }} />}
                        sx={{ color: 'text.tertiary', mb: 0.5 }}
                    >
                        Header
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                        {switches.map(sw => (
                            <Chip key={sw} size="sm" variant="outlined" color="neutral" sx={{ fontFamily: 'monospace' }}>
                                {sw}
                            </Chip>
                        ))}
                        {args.map((a, i) => (
                            <Chip
                                key={a.Key + i}
                                size="sm"
                                variant="soft"
                                color="neutral"
                                sx={{ fontFamily: 'monospace' }}
                                endDecorator={a.Value !== '' ? (
                                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', opacity: 0.75 }}>
                                        {a.Value}
                                    </Typography>
                                ) : null}
                            >
                                :{a.Key}
                            </Chip>
                        ))}
                    </Box>
                </Box>
            )}

            {/* The block as it is written, coloured by the highlighter the
                Files tab reads org with - so it looks the way it looks in the
                file rather than the way a form would show it. */}
            <Sheet
                variant="outlined"
                sx={{
                    borderRadius: 'sm', mb: 1.5, maxHeight: '46vh', overflow: 'auto',
                    borderLeft: '3px solid', borderLeftColor: `hsl(${hue} 70% 55%)`,
                }}
            >
                <OrgSource text={blockSource(block)} wrap openDrawers />
            </Sheet>

            {result && <RunResult res={result} onClear={onClearResult} />}

            {block.Result !== '' && (
                <Box sx={{ mb: 1 }}>
                    <Typography
                        level="body-xs"
                        startDecorator={<OutputIcon sx={{ fontSize: 15 }} />}
                        sx={{ color: 'text.tertiary', mb: 0.5 }}
                    >
                        Written in the file as {block.ResultKind !== '' && `a ${block.ResultKind}`}
                    </Typography>
                    <Sheet variant="soft" sx={{ borderRadius: 'sm', p: 1, maxHeight: 200, overflow: 'auto' }}>
                        <Typography
                            level="body-xs"
                            sx={{ fontFamily: 'monospace', whiteSpace: 'pre', fontSize: 11 }}
                        >
                            {block.Result}
                        </Typography>
                    </Sheet>
                </Box>
            )}

            <Divider sx={{ my: 1.5 }} />
            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontFamily: 'monospace', fontSize: 11 }}>
                {block.Filename.replace(/^.*\//, '')}:{block.Line + 1}–{block.EndLine + 1}
                {block.Lines > 0 && ` · ${block.Lines} line${block.Lines === 1 ? '' : 's'}`}
            </Typography>
        </Box>
    );
}

// ── The tab ─────────────────────────────────────────────────────────────────

export default function Code() {
    const [blocks, setBlocks] = React.useState<CodeBlock[] | null>(null);
    const [langs, setLangs] = React.useState<CodeLang[]>([]);
    const [total, setTotal] = React.useState(0);
    const [lang, setLang] = React.useState('');
    const [filter, setFilter] = React.useState('');
    const [picked, setPicked] = React.useState<string>('');
    const [error, setError] = React.useState('');
    const [groupBy, setGroupBy] = useSetting('codeGroupBy');
    const [folded, setFolded] = React.useState<Set<string>>(new Set());
    const [editing, setEditing] = React.useState(false);
    const [running, setRunning] = React.useState(false);
    // Keyed by block, so a result stays put while another is read and is
    // still there on the way back. A run is slow enough that losing it to a
    // stray click would be its own small tragedy.
    const [results, setResults] = React.useState<Record<string, CodeResult>>({});
    const nav = useNav();

    // A block has no identity of its own unless it has been named, so it is
    // addressed the way the server addresses one: its file and its place in it.
    const key = (b: CodeBlock) => `${b.Filename}#${b.Id}`;

    // The whole index in one request, filtered here. An org database has
    // hundreds of blocks rather than hundreds of thousands, and filtering in
    // the browser is what makes the language chips and the box feel like one
    // control rather than two round trips.
    const load = React.useCallback(async () => {
        try {
            const idx = await ODb.code();
            setBlocks(idx && Array.isArray(idx.Blocks) ? idx.Blocks : []);
            setLangs(idx && Array.isArray(idx.Langs) ? idx.Langs : []);
            setTotal(idx ? idx.Total : 0);
            setError('');
        } catch (e: any) {
            setError(e?.message || 'Could not read the code blocks.');
            setBlocks([]);
        }
    }, []);

    React.useEffect(() => { load(); }, [load]);

    // Back from the file, to the block they were reading.
    //
    // Two steps, and they have to be two: this panel is mounted by the switch
    // that set the restore, so it arrives before the index has been read and
    // there is nothing yet to pick. So it is taken straight away - leaving it
    // lying about would have some other panel find it later - and then held
    // until the block it names turns up.
    const restore = nav.restore;
    const [wanted, setWanted] = React.useState<any | null>(null);
    React.useEffect(() => {
        if (!restore || restore.tab !== 'Code') return;
        nav.tookRestore();
        setWanted(restore.filename ? restore : null);
    }, [restore, nav]);
    React.useEffect(() => {
        if (!wanted) return;
        const want = (blocks || []).find(b => b.Filename === wanted.filename && b.Id === wanted.id);
        if (!want) return;
        setPicked(key(want));
        setWanted(null);
    }, [wanted, blocks]);

    const shown = React.useMemo(() => {
        const all = blocks || [];
        const q = filter.trim().toLowerCase();
        return all.filter(b => {
            if (lang !== '' && (b.Lang || 'none') !== lang) return false;
            if (q === '') return true;
            if (b.Name.toLowerCase().includes(q)) return true;
            if ((b.Lang || '').toLowerCase().includes(q)) return true;
            if (b.Heading.toLowerCase().includes(q)) return true;
            if (b.Filename.toLowerCase().includes(q)) return true;
            if ((b.Code || '').toLowerCase().includes(q)) return true;
            return (b.Vars || []).some(v =>
                v.Name.toLowerCase().includes(q) || v.Ref.toLowerCase().includes(q));
        });
    }, [blocks, lang, filter]);


    const current = React.useMemo(
        () => shown.find(b => key(b) === picked) || null, [shown, picked]);

    // The list, with its bands in it. Grouping is a sort plus headers - the
    // same shape the search tab's grouping takes, and for the same reason: the
    // rows are the same rows, so nothing else in the list has to know.
    type Line =
        | { kind: 'band'; id: string; label: string; hint: string; count: number; hue: number }
        | { kind: 'row'; block: CodeBlock };

    const lines = React.useMemo<Line[]>(() => {
        if (groupBy === 'none') return shown.map(b => ({ kind: 'row' as const, block: b }));

        const by = new Map<string, CodeBlock[]>();
        for (const b of shown) {
            const k = groupBy === 'lang' ? (b.Lang || 'no language') : b.Filename;
            const got = by.get(k);
            if (got) got.push(b); else by.set(k, [b]);
        }
        const keys = Array.from(by.keys()).sort((a, c) =>
            // By the name you read rather than by the path, so two files
            // called notes.org sort together - which is what somebody
            // scanning a list of names expects. The Tables tab shows the
            // same name for the same reason.
            groupBy === 'file'
                ? baseName(a).localeCompare(baseName(c)) || a.localeCompare(c)
                : a.localeCompare(c));

        const out: Line[] = [];
        for (const k of keys) {
            const group = by.get(k) || [];
            out.push({
                kind: 'band',
                id: k,
                label: groupBy === 'file' ? baseName(k) : k,
                hint: groupBy === 'file' ? k : '',
                count: group.length,
                hue: langHue(groupBy === 'lang' ? k : group[0]?.Lang || ''),
            });
            if (folded.has(k)) continue;
            for (const b of group) out.push({ kind: 'row', block: b });
        }
        return out;
    }, [shown, groupBy, folded]);

    // A block that has fallen out of the filter should not leave its card up.
    React.useEffect(() => {
        if (picked !== '' && !shown.some(b => key(b) === picked)) setPicked('');
    }, [shown, picked]);

    const openAt = (file: string, line: number, heading?: string, from?: CodeBlock) =>
        nav.toFile({
            filename: file, line, heading,
            back: {
                app: 'Code', label: 'Back to code',
                where: from ? { tab: 'Code', filename: from.Filename, id: from.Id } : { tab: 'Code' },
            },
        });

    const run = async (b: CodeBlock, code?: string) => {
        setRunning(true);
        try {
            const res = await ODb.runCode({
                Filename: b.Filename, Id: b.Id,
                Code: code || '', SetCode: code !== undefined,
            });
            setResults(prev => ({ ...prev, [key(b)]: res }));
        } catch (e: any) {
            setResults(prev => ({
                ...prev,
                [key(b)]: {
                    Ok: false, Msg: e?.message || 'That did not go through.',
                    Kind: 'text', Result: '', Raw: '', Stderr: '', Code: -1, Seconds: 0,
                    File: '', Url: '', Exists: false, Bytes: 0,
                    Text: '', Truncated: false, Media: '', TextLang: '',
                },
            }));
        }
        setRunning(false);
    };

    // After a save the file has changed, so the whole index is read again:
    // an edit can move every block below it in the file, and a block is
    // addressed by its ordinal.
    const saved = async () => {
        setEditing(false);
        await new Promise(r => window.setTimeout(r, 400));
        await load();
    };

    return (
        <Box sx={{
            px: 2, pb: 1, display: 'flex', flexDirection: 'column',
            gap: 1.25, height: 'calc(100vh - 130px)', minHeight: 420,
        }}>
            {/* The languages in use, as a filter. Counts are of the whole
                database rather than of what is showing, so picking one can
                never empty the strip and leave no way back. */}
            {langs.length > 1 && (
                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
                    <Chip
                        variant={lang === '' ? 'solid' : 'soft'}
                        color={lang === '' ? 'primary' : 'neutral'}
                        onClick={() => setLang('')}
                        sx={{ cursor: 'pointer' }}
                    >
                        Everything
                    </Chip>
                    {langs.map(l => {
                        const hue = langHue(l.Lang);
                        const on = lang === l.Lang;
                        return (
                            <Chip
                                key={l.Lang}
                                variant={on ? 'solid' : 'soft'}
                                color={on ? 'primary' : 'neutral'}
                                onClick={() => setLang(on ? '' : l.Lang)}
                                startDecorator={
                                    <Box sx={{
                                        width: 7, height: 7, borderRadius: '50%',
                                        background: `hsl(${hue} 70% 55%)`,
                                    }} />
                                }
                                endDecorator={
                                    <Typography level="body-xs" sx={{ color: 'inherit', opacity: 0.7 }}>
                                        {l.Count}
                                    </Typography>
                                }
                                sx={{ cursor: 'pointer', fontFamily: 'monospace' }}
                            >
                                {l.Lang}
                            </Chip>
                        );
                    })}
                </Box>
            )}

            <SplitPane
                showDetail={!!current}
                onBack={() => setPicked('')}
                backLabel={current ? (current.Name || `${(current.Filename || '').replace(/^.*\//, '')}:${current.Id}`) : undefined}
                listWidth={360}
                list={(
                <Sheet
                    variant="outlined"
                    sx={{
                        flex: 1, borderRadius: 'sm',
                        display: 'flex', flexDirection: 'column', overflow: 'hidden',
                    }}
                >
                    <Box sx={{ p: 1.25, display: 'flex', gap: 0.75, alignItems: 'center' }}>
                        <Input
                            size="sm"
                            placeholder="Search the code, the names, the variables…"
                            value={filter}
                            onChange={e => setFilter(e.target.value)}
                            startDecorator={<SearchIcon />}
                            sx={{ flex: 1 }}
                        />
                        {/* How the list is gathered. Three ways of asking the
                            same list a different question: what matched, what
                            is written in each language, what is in each file. */}
                        <Box sx={{ display: 'flex', gap: 0.25, flexShrink: 0 }}>
                            {([
                                ['none', <ListOffIcon key="n" sx={{ fontSize: 17 }} />, 'One flat list'],
                                ['lang', <LayersIcon key="l" sx={{ fontSize: 17 }} />, 'Gather by language'],
                                ['file', <FolderIcon key="f" sx={{ fontSize: 17 }} />, 'Gather by file'],
                            ] as const).map(([mode, icon, title]) => (
                                <Tooltip key={mode} size="sm" title={title}>
                                    <IconButton
                                        size="sm"
                                        variant={groupBy === mode ? 'soft' : 'plain'}
                                        color={groupBy === mode ? 'primary' : 'neutral'}
                                        onClick={() => setGroupBy(mode)}
                                    >
                                        {icon}
                                    </IconButton>
                                </Tooltip>
                            ))}
                        </Box>
                    </Box>
                    <Divider />
                    <Box sx={{ flex: 1, overflowY: 'auto' }}>
                        {blocks === null ? (
                            <Box sx={{ p: 3, display: 'flex', justifyContent: 'center' }}>
                                <CircularProgress size="sm" />
                            </Box>
                        ) : shown.length === 0 ? (
                            <Box sx={{ p: 3, textAlign: 'center' }}>
                                <CodeIcon sx={{ fontSize: 34, opacity: 0.3 }} />
                                <Typography level="body-sm" sx={{ color: 'text.tertiary', mt: 1 }}>
                                    {total === 0
                                        ? 'No source blocks in these files yet.'
                                        : 'Nothing matches that.'}
                                </Typography>
                            </Box>
                        ) : lines.map(line => {
                            if (line.kind === 'band') {
                                const shut = folded.has(line.id);
                                return (
                                    <Box
                                        key={'band:' + line.id}
                                        onClick={() => setFolded(prev => {
                                            const next = new Set(prev);
                                            if (next.has(line.id)) next.delete(line.id);
                                            else next.add(line.id);
                                            return next;
                                        })}
                                        sx={{
                                            display: 'flex', alignItems: 'center', gap: 0.75,
                                            px: 1, py: 0.75, cursor: 'pointer',
                                            bgcolor: 'background.level1',
                                            borderTop: '1px solid', borderColor: 'divider',
                                            position: 'sticky', top: 0, zIndex: 1,
                                            '&:hover': { bgcolor: 'background.level2' },
                                        }}
                                    >
                                        <KeyboardArrowRightIcon
                                            sx={{
                                                fontSize: 15, color: 'text.tertiary', flexShrink: 0,
                                                transform: shut ? 'none' : 'rotate(90deg)',
                                                transition: 'transform 0.15s',
                                            }}
                                        />
                                        <Box sx={{
                                            width: 7, height: 7, borderRadius: '50%', flexShrink: 0,
                                            background: `hsl(${line.hue} 70% 55%)`,
                                        }} />
                                        <Tooltip size="sm" enterDelay={600} title={line.hint || ''}>
                                            <Typography
                                                level="body-xs"
                                                noWrap
                                                sx={{ fontWeight: 'lg', fontFamily: groupBy === 'lang' ? 'monospace' : undefined }}
                                            >
                                                {line.label}
                                            </Typography>
                                        </Tooltip>
                                        <Box sx={{ flex: 1 }} />
                                        <Chip size="sm" variant="soft" color="neutral" sx={{ '--Chip-minHeight': '17px', fontSize: 10 }}>
                                            {line.count}
                                        </Chip>
                                    </Box>
                                );
                            }
                            const b = line.block;
                            const on = key(b) === picked;
                            const hue = langHue(b.Lang);
                            const refs = referenceCount(b);
                            const broken = (b.Vars || []).some(isBrokenReference);
                            return (
                                <Box
                                    key={key(b)}
                                    onClick={() => { setPicked(key(b)); setEditing(false); }}
                                    sx={{
                                        display: 'flex', alignItems: 'flex-start', gap: 1,
                                        px: 1.25, py: 1, cursor: 'pointer',
                                        borderLeft: '3px solid',
                                        borderColor: on ? `hsl(${hue} 70% 55%)` : 'transparent',
                                        bgcolor: on ? 'background.level1' : 'transparent',
                                        '&:hover': { bgcolor: 'background.level1' },
                                    }}
                                >
                                    <Box sx={{
                                        width: 7, height: 7, borderRadius: '50%', flexShrink: 0, mt: '6px',
                                        background: `hsl(${hue} 70% 55%)`,
                                    }} />
                                    <Box sx={{ minWidth: 0, flex: 1 }}>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                                            <Typography
                                                level="body-sm"
                                                noWrap
                                                sx={{
                                                    fontWeight: on ? 'lg' : 'md',
                                                    fontFamily: b.Name ? 'monospace' : undefined,
                                                    fontStyle: b.Name ? undefined : 'italic',
                                                }}
                                            >
                                                {blockTitle(b)}
                                            </Typography>
                                            {/* A block that takes something out of the file is a
                                                step in a chain rather than a thing on its own,
                                                and that is worth seeing without opening it. */}
                                            {refs > 0 && (
                                                <Tooltip
                                                    size="sm"
                                                    title={broken
                                                        ? 'Takes something from the file — and one name resolves to nothing'
                                                        : `Takes ${refs} thing${refs === 1 ? '' : 's'} from the file`}
                                                >
                                                    <Chip
                                                        size="sm"
                                                        variant="soft"
                                                        color={broken ? 'danger' : 'primary'}
                                                        startDecorator={broken ? <WarningIcon sx={{ fontSize: 12 }} /> : <InputIcon sx={{ fontSize: 12 }} />}
                                                        sx={{ '--Chip-minHeight': '17px', fontSize: 10, flexShrink: 0 }}
                                                    >
                                                        {refs}
                                                    </Chip>
                                                </Tooltip>
                                            )}
                                        </Box>
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                                            {b.Filename.replace(/^.*\//, '')}:{b.Line + 1}
                                            {b.Lines > 0 && ` · ${b.Lines}L`}
                                            {b.Heading !== '' && ` · ${(b.Olp || []).slice(-1)[0]}`}
                                        </Typography>
                                    </Box>
                                </Box>
                            );
                        })}
                    </Box>
                    <Divider />
                    <Box sx={{ px: 1.25, py: 0.75 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {blocks === null ? '…' : shown.length === total
                                ? `${total} block${total === 1 ? '' : 's'}`
                                : `${shown.length} of ${total}`}
                        </Typography>
                    </Box>
                </Sheet>
                )}
                detail={(
                <Sheet variant="outlined" sx={{ flex: 1, borderRadius: 'sm', overflow: 'hidden', minWidth: 0 }}>
                    {error !== '' ? (
                        <Box sx={{ p: 3 }}>
                            <Typography level="body-sm" color="danger">{error}</Typography>
                        </Box>
                    ) : current && editing ? (
                        <BlockEditor
                            block={current}
                            onSaved={saved}
                            onCancel={() => setEditing(false)}
                            onRun={code => run(current, code)}
                        />
                    ) : current ? (
                        <BlockCard
                            block={current}
                            onOpen={openAt}
                            onRun={() => run(current)}
                            onEdit={() => setEditing(true)}
                            running={running}
                            result={results[key(current)] || null}
                            onClearResult={() => setResults(prev => {
                                const next = { ...prev };
                                delete next[key(current)];
                                return next;
                            })}
                        />
                    ) : (
                        <Box sx={{
                            height: '100%', display: 'flex', flexDirection: 'column',
                            alignItems: 'center', justifyContent: 'center', gap: 0.5, color: 'text.tertiary',
                        }}>
                            <CodeIcon sx={{ fontSize: 40, opacity: 0.3 }} />
                            <Typography level="body-sm">Pick a block to read it.</Typography>
                            <Typography level="body-xs" sx={{ maxWidth: 320, textAlign: 'center' }}>
                                A block that takes a table or another block's results is marked in
                                the list, and says what it points at when you open it.
                            </Typography>
                        </Box>
                    )}
                </Sheet>
                )}
            />
        </Box>
    );
}
