// Quick capture.
//
// Press c anywhere, or the pencil on the rail, and this comes up: pick a
// template, fill in what it asks for, and the thing is filed where the
// template says. It is the same journey `orgs cap` takes in the terminal, and
// it talks to the same two endpoints.
//
// Three things are worth knowing about the shape of it.
//
// The *template string* is the form. The server does nothing with it - it says
// so in the type's own comment - so what a template asks for is read here
// (src/capture.ts) and put up as fields. A template with no string asks for a
// headline and a body, which is what every template in the shipped config is.
//
// The dialog takes a *colour from the template's name*, so the one you use
// every day is recognisable before you have read anything. And it shows what
// will land in the file, coloured by the same highlighter the Files tab uses,
// because the thing being checked is the org text rather than the form.
//
// Dictating and pasting a picture both work because a capture is exactly when
// you have something and no time: the words go into whichever box the cursor
// was in, and the picture is kept straight away and linked - see
// internal/app/orgs/capturestash.go for why keeping it needs the template.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Textarea from '@mui/joy/Textarea';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Chip from '@mui/joy/Chip';
import Divider from '@mui/joy/Divider';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import CircularProgress from '@mui/joy/CircularProgress';
import Tooltip from '@mui/joy/Tooltip';

import SearchIcon from '@mui/icons-material/Search';
import MicIcon from '@mui/icons-material/Mic';
import StopCircleIcon from '@mui/icons-material/StopCircle';
import CheckIcon from '@mui/icons-material/Check';
import ImageIcon from '@mui/icons-material/ImageOutlined';
import ScheduleIcon from '@mui/icons-material/ScheduleOutlined';
import ArrowBackIcon from '@mui/icons-material/ArrowBackIosNew';

import { ODb } from '../db';
import {
    CaptureTemplate, CaptureField,
    templateFields, fillTemplate, needsHeadline, targetText, templateHue, previewOf,
} from '../capture';
import { pickMimeType, extFor, formatClock } from '../voice';
import OrgSource from './OrgSource';

// ── Dictating ───────────────────────────────────────────────────────────────

type VoicePhase = 'idle' | 'asking' | 'recording' | 'working';

// The mic, wired to whatever box the cursor was last in.
//
// The order is the voice notes' order and for the same reason: the recording
// is saved the moment recording stops, before anything is attempted on it. A
// transcription fails in a dozen ways and none of them should cost the words
// that were said - so even when whisper says nothing, the audio is kept and
// its link goes into the capture, where it can be listened to later.
function Dictate({ template, onText, onLink, onArm, into }: {
    template: string;
    onText: (text: string) => void;
    onLink: (link: string) => void;
    // Called on mouse down, before the button takes the focus, so the form can
    // note which box the cursor was in. Reading it afterwards is too late:
    // pressing a button moves the focus to the button.
    onArm?: () => void;
    // What that box is called, for the tooltip. Somebody about to dictate
    // should be able to see where the words are going to land.
    into?: string;
}) {
    const [phase, setPhase] = React.useState<VoicePhase>('idle');
    const [seconds, setSeconds] = React.useState(0);
    const [msg, setMsg] = React.useState('');

    const recorder = React.useRef<MediaRecorder | null>(null);
    const chunks = React.useRef<Blob[]>([]);
    const stream = React.useRef<MediaStream | null>(null);
    const started = React.useRef(0);
    const ticker = React.useRef<number | null>(null);
    const alive = React.useRef(true);

    React.useEffect(() => () => {
        alive.current = false;
        if (ticker.current !== null) window.clearInterval(ticker.current);
        if (stream.current) stream.current.getTracks().forEach(t => t.stop());
    }, []);

    const letGo = () => {
        if (ticker.current !== null) { window.clearInterval(ticker.current); ticker.current = null; }
        if (stream.current) { stream.current.getTracks().forEach(t => t.stop()); stream.current = null; }
        recorder.current = null;
    };

    const finish = async (blob: Blob, mime: string, took: number) => {
        setPhase('working');
        setMsg('Keeping the recording…');
        try {
            const rec = await ODb.saveVoiceRecording(blob, took, `capture.${extFor(mime)}`);
            if (!rec || !rec.id) {
                setMsg('The recording could not be saved.');
                setPhase('idle');
                return;
            }
            setMsg('Asking whisper what it says…');
            let text = '';
            try {
                const t = await ODb.transcribeVoice(rec.id);
                text = ((t && t.text) || '').trim();
            } catch {
                text = '';
            }
            if (!alive.current) return;
            if (text !== '') onText(text);
            try {
                const l = await ODb.voiceLink(rec.id, template);
                if (alive.current && l && l.Ok && l.link) onLink(l.link);
            } catch { /* the words matter more than the link */ }
            if (!alive.current) return;
            setMsg(text === '' ? 'Whisper had nothing — the recording is linked.' : '');
            setPhase('idle');
            window.setTimeout(() => { if (alive.current) setMsg(''); }, 4000);
        } catch (e: any) {
            if (!alive.current) return;
            setMsg((e && e.message) || 'That did not go through.');
            setPhase('idle');
        }
    };

    const start = async () => {
        setMsg('');
        setPhase('asking');
        try {
            const media = await navigator.mediaDevices.getUserMedia({ audio: true });
            if (!alive.current) { media.getTracks().forEach(t => t.stop()); return; }
            stream.current = media;
            const mime = pickMimeType(t => !!(window as any).MediaRecorder && MediaRecorder.isTypeSupported(t));
            const rec = mime ? new MediaRecorder(media, { mimeType: mime }) : new MediaRecorder(media);
            chunks.current = [];
            rec.ondataavailable = e => { if (e.data && e.data.size > 0) chunks.current.push(e.data); };
            rec.onstop = () => {
                const took = (Date.now() - started.current) / 1000;
                const blob = new Blob(chunks.current, { type: rec.mimeType || mime || 'audio/webm' });
                letGo();
                if (blob.size === 0) { setMsg('Nothing was recorded.'); setPhase('idle'); return; }
                finish(blob, rec.mimeType || mime || 'audio/webm', took);
            };
            recorder.current = rec;
            started.current = Date.now();
            setSeconds(0);
            rec.start();
            setPhase('recording');
            ticker.current = window.setInterval(() => setSeconds((Date.now() - started.current) / 1000), 250);
        } catch {
            letGo();
            setMsg('This browser would not give up the microphone.');
            setPhase('idle');
        }
    };

    const stop = () => {
        const rec = recorder.current;
        if (!rec) { letGo(); setPhase('idle'); return; }
        try { rec.stop(); } catch { letGo(); setPhase('idle'); }
    };

    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
            {phase === 'recording' ? (
                <Tooltip size="sm" title="Stop and write it down">
                    <IconButton size="sm" variant="solid" color="danger" onClick={stop}>
                        <StopCircleIcon />
                    </IconButton>
                </Tooltip>
            ) : phase === 'working' || phase === 'asking' ? (
                <CircularProgress size="sm" />
            ) : (
                <Tooltip size="sm" title={into ? `Say it — the words go into ${into}` : 'Say it instead of typing it'}>
                    <IconButton
                        size="sm"
                        variant="soft"
                        color="neutral"
                        // On the way past as well as on the way down: the
                        // tooltip has to name the right box while it is being
                        // read, which is before anything is pressed.
                        onMouseEnter={() => onArm?.()}
                        onFocus={() => onArm?.()}
                        onMouseDown={() => onArm?.()}
                        onClick={start}
                    >
                        <MicIcon />
                    </IconButton>
                </Tooltip>
            )}
            {phase === 'recording' && (
                <Typography level="body-xs" sx={{ fontFamily: 'monospace', color: 'danger.500' }}>
                    {formatClock(seconds)}
                </Typography>
            )}
            {msg !== '' && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{msg}</Typography>
            )}
        </Box>
    );
}

// ── Picking a template ──────────────────────────────────────────────────────

function Pick({ templates, onPick }: {
    templates: CaptureTemplate[];
    onPick: (t: CaptureTemplate) => void;
}) {
    const [filter, setFilter] = React.useState('');
    const [at, setAt] = React.useState(0);

    const shown = React.useMemo(() => {
        const q = filter.trim().toLowerCase();
        if (q === '') return templates;
        return templates.filter(t =>
            t.Name.toLowerCase().includes(q) ||
            (t.Type || '').toLowerCase().includes(q) ||
            targetText(t).toLowerCase().includes(q));
    }, [templates, filter]);

    React.useEffect(() => { setAt(0); }, [filter]);

    // The list is driven from the box, so the arrow keys work without ever
    // leaving it - which is the whole point of a quick capture.
    const onKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') { e.preventDefault(); setAt(i => Math.min(i + 1, shown.length - 1)); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); setAt(i => Math.max(i - 1, 0)); }
        else if (e.key === 'Enter' && shown[at]) { e.preventDefault(); onPick(shown[at]); }
    };

    return (
        <Box>
            <Input
                size="sm"
                autoFocus
                placeholder="Which template?"
                value={filter}
                onChange={e => setFilter(e.target.value)}
                onKeyDown={onKey}
                startDecorator={<SearchIcon />}
                sx={{ mb: 1 }}
            />
            <Sheet variant="outlined" sx={{ borderRadius: 'sm', maxHeight: 340, overflowY: 'auto' }}>
                {shown.length === 0 ? (
                    <Box sx={{ p: 2, textAlign: 'center' }}>
                        <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>
                            {templates.length === 0
                                ? 'This server has no capture templates. They go under captureTemplates: in orgs.yaml.'
                                : 'Nothing matches that.'}
                        </Typography>
                    </Box>
                ) : shown.map((t, i) => {
                    const hue = templateHue(t.Name);
                    return (
                        <Box
                            key={t.Name}
                            onClick={() => onPick(t)}
                            onMouseEnter={() => setAt(i)}
                            sx={{
                                display: 'flex', alignItems: 'center', gap: 1.25, px: 1.25, py: 1,
                                cursor: 'pointer',
                                borderLeft: '3px solid',
                                borderColor: i === at ? `hsl(${hue} 70% 55%)` : 'transparent',
                                bgcolor: i === at ? 'background.level1' : 'transparent',
                            }}
                        >
                            <Box sx={{
                                width: 8, height: 8, borderRadius: '50%', flexShrink: 0,
                                background: `hsl(${hue} 70% 55%)`,
                            }} />
                            <Box sx={{ minWidth: 0, flex: 1 }}>
                                <Typography level="body-sm" sx={{ fontWeight: 'md' }} noWrap>{t.Name}</Typography>
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                                    {targetText(t)}
                                </Typography>
                            </Box>
                            <Chip size="sm" variant="soft" color="neutral">{t.Type || 'entry'}</Chip>
                        </Box>
                    );
                })}
            </Sheet>
            <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                ↑↓ to move, Enter to take it, Esc to give up.
            </Typography>
        </Box>
    );
}

// ── Filling one in ──────────────────────────────────────────────────────────

function Fill({ template, onDone, onBack }: {
    template: CaptureTemplate;
    onDone: (msg: string) => void;
    onBack: () => void;
}) {
    const hue = templateHue(template.Name);
    const fields = React.useMemo(() => templateFields(template.Template), [template]);
    const [values, setValues] = React.useState<Record<string, string>>(() => {
        const v: Record<string, string> = {};
        for (const f of fields) v[f.key] = f.initial;
        return v;
    });
    const [headline, setHeadline] = React.useState('');
    const [tagText, setTagText] = React.useState('');
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');
    const [shots, setShots] = React.useState<string[]>([]);

    const wantsHead = needsHeadline(template.Type);
    const contentField = fields.find(f => f.kind === 'content');

    // Which box a dictation or a pasted link lands in: the one the cursor was
    // in when the mic was pressed.
    //
    // Every box carries its own key in a data attribute and `arm` reads it off
    // whatever has the focus, rather than trusting a focus handler to have
    // fired. That matters because pressing the mic *moves* the focus onto the
    // mic - so the question has to be asked on mouse down, and the answer has
    // to come from the document rather than from a state this form kept.
    const lastBox = React.useRef<string>(contentField ? contentField.key : (fields[0]?.key || ''));
    const heads = React.useRef<HTMLInputElement | null>(null);
    const form = React.useRef<HTMLDivElement | null>(null);

    const arm = () => {
        const el = document.activeElement as HTMLElement | null;
        const box = el?.closest?.('[data-cap-key]') as HTMLElement | null;
        const key = box?.getAttribute('data-cap-key');
        // Nothing focused, or the focus is somewhere that is not a box of
        // ours: leave the last answer standing rather than guessing.
        if (key) lastBox.current = key;
    };

    // What to call the box the words are going into, for the tooltip.
    const nameOf = (key: string): string => {
        if (key === '__headline') return 'the headline';
        const f = fields.find(x => x.key === key);
        return f ? f.prompt.toLowerCase().replace(/\?$/, '') : 'the body';
    };
    const [armed, setArmed] = React.useState(lastBox.current);
    // The tooltip appears on hover, which is before the mouse goes down - so
    // the name it shows is worked out then as well.
    const peek = () => { arm(); setArmed(lastBox.current); };

    const setValue = (key: string, v: string) => setValues(p => ({ ...p, [key]: v }));

    // Appended at the end of what is already there. A line of prose joins the
    // body on a line of its own; a one-line field joins with a space, because
    // a newline inside an <input> is a character nobody can see and the server
    // would write it as a property value with a line break in it.
    const appendTo = (key: string, text: string) => {
        if (key === '__headline') { setHeadline(h => (h ? h.trimEnd() + ' ' : '') + text); return; }
        const multiline = contentField !== undefined && key === contentField.key;
        setValues(p => {
            const was = p[key] || '';
            if (was === '') return { ...p, [key]: text };
            if (!multiline) return { ...p, [key]: was.trimEnd() + ' ' + text };
            return { ...p, [key]: was.endsWith('\n') ? was + text : was + '\n' + text };
        });
    };

    const tags = tagText.split(/[\s,]+/).map(t => t.trim()).filter(Boolean);
    const body = fillTemplate(template.Template, values);
    const preview = previewOf(template, headline, tags, body);

    // A picture on the clipboard is kept straight away and linked, because a
    // capture has no heading to hang it on until it is made. The link goes
    // into the body where the words are.
    const onPaste = async (e: React.ClipboardEvent) => {
        const items = Array.from(e.clipboardData?.items || []);
        const pic = items.find(i => i.kind === 'file' && i.type.startsWith('image/'));
        if (!pic) return;
        const blob = pic.getAsFile();
        if (!blob) return;
        e.preventDefault();
        setError('');
        try {
            const res = await ODb.stashImage(blob, blob.type, blob.name || 'paste.png', template.Name);
            if (!res || !res.Ok) { setError((res && res.Msg) || 'That picture could not be kept.'); return; }
            appendTo(contentField ? contentField.key : lastBox.current, `[[file:${res.link}]]`);
            if (res.url) setShots(s => [...s, res.url]);
        } catch (err: any) {
            setError((err && err.message) || 'That picture could not be kept.');
        }
    };

    const save = async () => {
        if (wantsHead && headline.trim() === '') {
            setError('An entry needs a headline.');
            heads.current?.focus();
            return;
        }
        setBusy(true);
        setError('');
        try {
            const res = await ODb.capture({
                Template: template.Name,
                NewNode: { Headline: headline.trim(), Content: body, Tags: tags },
            });
            if (!res || res.Ok === false) {
                setError((res && res.Msg) || 'The server would not file that.');
                setBusy(false);
                return;
            }
            onDone(`Captured into ${targetText(template)}`);
        } catch (e: any) {
            setError((e && e.message) || 'That did not go through.');
            setBusy(false);
        }
    };

    // Ctrl/Cmd+Enter files it from anywhere in the form, which is the only way
    // a quick capture is quick - reaching for the button with the mouse is the
    // thing this whole dialog exists to avoid.
    const onKey = (e: React.KeyboardEvent) => {
        if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); save(); }
    };

    return (
        <Box onPaste={onPaste} onKeyDown={onKey}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1.5 }}>
                <IconButton size="sm" variant="plain" color="neutral" onClick={onBack} title="Another template">
                    <ArrowBackIcon sx={{ fontSize: 15 }} />
                </IconButton>
                <Box sx={{ minWidth: 0 }}>
                    <Typography level="title-md" sx={{ color: `hsl(${hue} 60% 42%)` }}>
                        {template.Name}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                        {template.Type || 'entry'} · {targetText(template)}
                    </Typography>
                </Box>
                <Box sx={{ flex: 1 }} />
                {/* Room for the dialog's own close button, which sits in this
                    corner. */}
                <Box sx={{ width: 26, flexShrink: 0 }} />
            </Box>

            {wantsHead && (
                <Input
                    size="lg"
                    autoFocus
                    placeholder="What is it?"
                    value={headline}
                    onChange={e => setHeadline(e.target.value)}
                    onFocus={() => { lastBox.current = '__headline'; }}
                    data-cap-key="__headline"
                    slotProps={{ input: { ref: heads } }}
                    sx={{
                        mb: 1,
                        '--Input-focusedHighlight': `hsl(${hue} 70% 55%)`,
                    }}
                />
            )}

            {wantsHead && (
                <Input
                    size="sm"
                    placeholder="Tags, spaces between them"
                    value={tagText}
                    onChange={e => setTagText(e.target.value)}
                    sx={{ mb: 1.25 }}
                    endDecorator={tags.length > 0 ? (
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                            {tags.slice(0, 4).map(t => (
                                <Chip key={t} size="sm" variant="soft" color="primary">{t}</Chip>
                            ))}
                        </Box>
                    ) : null}
                />
            )}

            {!contentField && (
                <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 0.5 }}>
                    <Dictate
                        template={template.Name}
                        into={nameOf(armed)}
                        onArm={peek}
                        onText={t => appendTo(lastBox.current, t)}
                        onLink={l => appendTo(lastBox.current, `[[file:${l}]]`)}
                    />
                </Box>
            )}

            {fields.filter(f => f.kind === 'text').map(f => (
                <Box key={f.key} sx={{ mb: 1 }}>
                    <Typography
                        level="body-xs"
                        sx={{ color: 'text.tertiary', mb: 0.25 }}
                        endDecorator={f.auto
                            ? <ScheduleIcon sx={{ fontSize: 13, opacity: 0.7 }} />
                            : null}
                    >
                        {f.prompt}
                    </Typography>
                    <Input
                        size="sm"
                        value={values[f.key] || ''}
                        onChange={e => setValue(f.key, e.target.value)}
                        onFocus={() => { lastBox.current = f.key; }}
                        data-cap-key={f.key}
                        placeholder={f.auto ? f.initial : ''}
                    />
                </Box>
            ))}

            {contentField && (
                <Box sx={{ mb: 1.25 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.25 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {contentField.prompt}
                        </Typography>
                        <Box sx={{ flex: 1 }} />
                        {/* The mic is here rather than in the title bar: it
                            writes into a box, and this is the box it writes
                            into unless another one was touched last. */}
                        <Dictate
                            template={template.Name}
                            into={nameOf(armed)}
                            onArm={peek}
                            onText={t => appendTo(lastBox.current, t)}
                            // The audio always goes with the body, wherever the
                            // words went: a file link in a one-line property is
                            // a property nobody can read.
                            onLink={l => appendTo(contentField.key, `[[file:${l}]]`)}
                        />
                    </Box>
                    <Textarea
                        minRows={4}
                        maxRows={12}
                        placeholder="Type it, say it, or paste a picture in."
                        value={values[contentField.key] || ''}
                        onChange={e => setValue(contentField.key, e.target.value)}
                        onFocus={() => { lastBox.current = contentField.key; }}
                        data-cap-key={contentField.key}
                        sx={{ '--Textarea-focusedHighlight': `hsl(${hue} 70% 55%)` }}
                    />
                </Box>
            )}

            {shots.length > 0 && (
                <Box sx={{ display: 'flex', gap: 0.75, mb: 1.25, flexWrap: 'wrap' }}>
                    {shots.map(src => (
                        <Box
                            key={src}
                            component="img"
                            src={src}
                            alt="pasted"
                            sx={{
                                height: 54, borderRadius: 'sm',
                                boxShadow: 'inset 0 0 0 1px var(--joy-palette-divider)',
                            }}
                        />
                    ))}
                    <Chip size="sm" variant="soft" color="neutral" startDecorator={<ImageIcon sx={{ fontSize: 15 }} />}>
                        kept and linked
                    </Chip>
                </Box>
            )}

            {/* What lands in the file, coloured by the same highlighter the
                Files tab reads org with - the thing being checked is the org
                text rather than the form. */}
            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.25 }}>Goes in as</Typography>
            <Sheet
                variant="outlined"
                sx={{
                    borderRadius: 'sm', mb: 1.5, maxHeight: 180, overflow: 'auto',
                    borderLeft: '3px solid', borderLeftColor: `hsl(${hue} 70% 55%)`,
                }}
            >
                <OrgSource text={preview} wrap openDrawers />
            </Sheet>

            {error !== '' && (
                <Typography level="body-sm" color="danger" sx={{ mb: 1 }}>{error}</Typography>
            )}

            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                <Button size="sm" onClick={save} loading={busy} startDecorator={<CheckIcon />}>
                    Capture
                </Button>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    ⌘/Ctrl + Enter
                </Typography>
            </Box>
        </Box>
    );
}

// ── The dialog ──────────────────────────────────────────────────────────────

export default function Capture({ open, template = '', onClose }: {
    open: boolean;
    // A template to go straight to, by name. Set when the capture was asked
    // for by name from the command palette; the picker is skipped for the same
    // reason it is skipped when there is only one template - the choice has
    // already been made.
    template?: string;
    onClose: () => void;
}) {
    const [templates, setTemplates] = React.useState<CaptureTemplate[] | null>(null);
    const [picked, setPicked] = React.useState<CaptureTemplate | null>(null);
    const [said, setSaid] = React.useState('');
    const [error, setError] = React.useState('');

    React.useEffect(() => {
        if (!open) return;
        setPicked(null);
        setSaid('');
        setError('');
        setTemplates(null);
        ODb.captureTemplates()
            .then(ts => {
                setTemplates(ts);
                // One template is not a choice. Going straight to the form
                // saves a keystroke on every capture for anybody who has one.
                if (ts.length === 1) setPicked(ts[0]);
                else if (template !== '') {
                    const want = ts.find(t => t.Name === template);
                    if (want) setPicked(want);
                }
            })
            .catch(e => { setError((e && e.message) || 'Could not ask for the templates.'); setTemplates([]); });
    }, [open, template]);

    const done = (msg: string) => {
        setSaid(msg);
        // Long enough to read, short enough that it is out of the way before
        // the next thing occurs to you.
        window.setTimeout(() => { setSaid(''); onClose(); }, 1100);
    };

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog
                sx={{
                    width: 620, maxWidth: '94vw', maxHeight: '92vh', overflowY: 'auto',
                    // Anchored near the top rather than centred: the dialog
                    // grows as the template asks for more, and a box that
                    // grows from its middle moves everything already typed.
                    top: '7vh', transform: 'translateX(-50%)', left: '50%',
                }}
            >
                <ModalClose />
                {said !== '' ? (
                    <Box sx={{ py: 4, textAlign: 'center' }}>
                        <CheckIcon sx={{ fontSize: 34, color: 'success.500' }} />
                        <Typography level="title-md" sx={{ mt: 1 }}>{said}</Typography>
                    </Box>
                ) : templates === null ? (
                    <Box sx={{ py: 5, display: 'flex', justifyContent: 'center' }}>
                        <CircularProgress size="sm" />
                    </Box>
                ) : error !== '' ? (
                    <Typography level="body-sm" color="danger" sx={{ py: 2 }}>{error}</Typography>
                ) : picked ? (
                    <Fill template={picked} onDone={done} onBack={() => setPicked(null)} />
                ) : (
                    <>
                        <Typography level="title-md" sx={{ mb: 0.25 }}>Capture</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1.25 }}>
                            Something now, filed properly, without leaving what you were doing.
                        </Typography>
                        <Divider sx={{ mb: 1.25 }} />
                        <Pick templates={templates} onPick={setPicked} />
                    </>
                )}
            </ModalDialog>
        </Modal>
    );
}

// Whether a key press is somebody typing rather than reaching for a shortcut.
// A bare letter can only be a shortcut when the letter is not going into
// something.
export function isTyping(target: EventTarget | null): boolean {
    const el = target as HTMLElement | null;
    if (!el) return false;
    const tag = (el.tagName || '').toUpperCase();
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable === true;
}
